<?php
declare(strict_types=1);
function vista_inicio(string $titulo):void{$GLOBALS['titulo']=$titulo;require __DIR__.'/comunes/encabezado.php';}
function vista_fin():void{require __DIR__.'/comunes/pie.php';}
function id_get():int{$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id)abortar(400,'Identificador inválido.');return $id;}
function requerido(string $k,int $max=1000):string{$v=trim((string)($_POST[$k]??''));if($v===''||mb_strlen($v)>$max)abortar(422,"El campo {$k} es obligatorio o excede el largo permitido.");return $v;}
function pagina_login():void{if(usuario())redirigir('inicio');vista_inicio('Acceso');?><section class="tarjeta login"><a class="marca" href="index.php"><img src="assets/logo.svg" alt="">ClinicVet</a><h1>Ingresar</h1><form action="index.php?r=login.enviar" method="post" data-no-warn><?=campo_csrf()?><label>Correo<input type="email" name="email" required autocomplete="username"></label><label>Contraseña<input type="password" name="password" required autocomplete="current-password"></label><button type="submit">Ingresar</button></form></section><?php vista_fin();}
function accion_login():void{post();$email=mb_strtolower(trim((string)($_POST['email']??'')));$u=fila('SELECT * FROM usuarios WHERE email=? AND activo=1',[$email]);$ok=$u&&(!$u['bloqueado_hasta']||strtotime($u['bloqueado_hasta'])<=time())&&password_verify((string)($_POST['password']??''),$u['password_hash']);if(!$ok){if($u){$n=(int)$u['intentos_fallidos']+1;$hasta=$n>=5?gmdate('Y-m-d H:i:s',time()+900):null;ejecutar('UPDATE usuarios SET intentos_fallidos=?,bloqueado_hasta=? WHERE id=?',[$n,$hasta,$u['id']]);}flash('error','Correo o contraseña incorrectos.');redirigir('login');}session_regenerate_id(true);$_SESSION['usuario']=['id'=>(int)$u['id'],'nombre'=>$u['nombre'],'rol'=>$u['rol']];ejecutar('UPDATE usuarios SET intentos_fallidos=0,bloqueado_hasta=NULL,ultimo_acceso=UTC_TIMESTAMP() WHERE id=?',[$u['id']]);auditar('login','usuarios',$u['id']);redirigir('inicio');}
function accion_logout():void{post();auditar('logout','usuarios',usuario()['id']);$_SESSION=[];session_destroy();session_start();flash('ok','Sesión cerrada.');redirigir('login');}
function pagina_inicio():void{$desde=gmdate('Y-m-d 00:00:00');$ops=['pacientes'=>(int)fila('SELECT COUNT(DISTINCT paciente_id) n FROM atenciones WHERE estado="finalizada" AND fecha_clinica>=?',[$desde])['n'],'atenciones'=>(int)fila('SELECT COUNT(*) n FROM atenciones WHERE estado="finalizada" AND fecha_clinica>=?',[$desde])['n'],'controles'=>(int)fila('SELECT COUNT(*) n FROM atenciones WHERE estado!="anulada" AND proximo_control BETWEEN CURRENT_DATE AND DATE_ADD(CURRENT_DATE,INTERVAL 30 DAY)')['n'],'stock'=>(int)fila('SELECT COUNT(*) n FROM productos p WHERE activo=1 AND (SELECT COALESCE(SUM(saldo_base),0) FROM lotes WHERE producto_id=p.id AND (vencimiento IS NULL OR vencimiento>=CURRENT_DATE))<=stock_minimo')['n']];vista_inicio('Inicio');?><section class="bienvenida"><div><span class="sobrelinea">CENTRO DE OPERACIONES</span><h1>¿Qué necesitas hacer ahora?</h1><p>Comienza por buscar a la mascota o registrar una llegada nueva.</p></div><div class="acciones-principales"><a class="boton boton-grande" href="index.php?r=recepcion">Recibir un paciente</a><a class="boton secundario boton-grande" href="index.php?r=atenciones">Ver atenciones de hoy</a></div></section><h2 class="titulo-seccion">Resumen de hoy <small><?=e(date('d-m-Y'))?></small></h2><div class="rejilla"><?php foreach(['Pacientes atendidos'=>$ops['pacientes'],'Atenciones finalizadas'=>$ops['atenciones'],'Próximos controles'=>$ops['controles'],'Alertas de stock'=>$ops['stock']] as $n=>$v):?><article class="tarjeta metrica"><span><?=e($n)?></span><strong><?=$v?></strong></article><?php endforeach;?></div><?php if(es_superadmin()):$ing=(int)fila('SELECT COALESCE(SUM(p.importe),0)-COALESCE((SELECT SUM(d.importe) FROM devoluciones d WHERE d.fecha>=?),0) n FROM pagos p LEFT JOIN anulaciones_pago a ON a.pago_id=p.id WHERE a.id IS NULL AND p.fecha>=?',[$desde,$desde])['n'];$gas=(int)fila('SELECT COALESCE(SUM(importe),0) n FROM movimientos_financieros WHERE tipo="gasto" AND estado="vigente" AND fecha>=?',[$desde])['n'];?><h2 class="titulo-seccion">Resumen financiero</h2><div class="rejilla"><article class="tarjeta metrica"><span>Cobros netos recibidos</span><strong><?=clp($ing)?></strong></article><article class="tarjeta metrica"><span>Gastos pagados</span><strong><?=clp($gas)?></strong></article><article class="tarjeta metrica"><span>Flujo</span><strong><?=clp($ing-$gas)?></strong></article></div><?php endif;vista_fin();}
function pagina_recepcion():void{$q=trim((string)($_GET['q']??''));$rs=[];if($q!==''){$l='%'.$q.'%';$rs=filas('SELECT p.id,p.codigo,p.nombre,p.especie,p.alertas_clinicas,t.nombre tutor,t.telefono FROM pacientes p JOIN tutores t ON t.id=p.tutor_id WHERE p.estado="activo" AND (p.nombre LIKE ? OR p.codigo LIKE ? OR t.nombre LIKE ? OR t.telefono LIKE ?) ORDER BY p.nombre LIMIT 20',[$l,$l,$l,$l]);}vista_inicio('Recepción');?><nav class="pasos" aria-label="Proceso de atención"><span class="activo"><b>1</b> Recepción</span><span><b>2</b> Atención clínica</span><span><b>3</b> Servicios e insumos</span><span><b>4</b> Cobro</span></nav><section class="cabecera-flujo"><span class="sobrelinea">LLEGADA DEL PACIENTE</span><h1>Busca antes de registrar</h1><p>Encuentra por mascota, código, tutor o teléfono. Así evitas fichas duplicadas.</p></section><form class="buscador-recepcion" action="index.php" method="get" data-no-warn><input type="hidden" name="r" value="recepcion"><label class="sr-only" for="rq">Buscar paciente o tutor</label><input id="rq" name="q" value="<?=e($q)?>" placeholder="Ej: Luna, CV-102, Ana Pérez o 9 1234 5678" autofocus><button>Buscar</button></form><?php if($q!==''):?><section class="resultados-recepcion"><div class="cabecera"><div><h2>Resultados</h2><p><?=count($rs)?> coincidencia(s)</p></div><button class="boton secundario" type="button" data-abrir-alta>No aparece, registrar nuevo</button></div><?php if(!$rs):?><div class="tarjeta estado-vacio"><h3>No encontramos coincidencias</h3><p>Revisa el nombre o teléfono. Si es su primera visita, registra tutor y mascota en un solo paso.</p><button type="button" data-abrir-alta>Registrar llegada nueva</button></div><?php endif;foreach($rs as $r):?><article class="paciente-resultado"><div class="avatar-mascota"><?=e(mb_substr($r['nombre'],0,1))?></div><div><h3><?=e($r['nombre'])?> <small><?=e($r['codigo'])?></small></h3><p><?=e($r['especie'])?> · Tutor: <?=e($r['tutor'])?> · <?=e($r['telefono']?:'sin teléfono')?></p><?php if($r['alertas_clinicas']):?><span class="aviso-clinico">⚠ <?=e($r['alertas_clinicas'])?></span><?php endif;?></div><div class="acciones"><a class="boton secundario" href="index.php?r=paciente.ficha&amp;id=<?=$r['id']?>">Ver ficha</a><a class="boton" href="index.php?r=atencion.form&amp;paciente_id=<?=$r['id']?>">Iniciar atención</a></div></article><?php endforeach;?></section><?php endif;?><section class="tarjeta alta-rapida <?=$q!==''&&$rs?'oculto':''?>" id="alta-rapida"><div class="cabecera"><div><span class="sobrelinea">PRIMERA VISITA</span><h2>Registrar tutor y mascota</h2><p>Completa solo lo necesario para comenzar; el resto puede agregarse después.</p></div></div><form class="form-grid" action="index.php?r=recepcion.guardar" method="post"><?=campo_csrf()?><div class="seccion-form ancho"><span>1</span><div><h3>Datos del tutor</h3><p>Persona responsable y medio de contacto.</p></div></div><label>Nombre del tutor *<input name="tutor_nombre" required maxlength="160"></label><label>Teléfono principal *<input name="telefono" required maxlength="30" inputmode="tel"></label><label>Correo<input type="email" name="email" maxlength="190"></label><label>RUT o identificación<input name="identificacion" maxlength="30"></label><div class="seccion-form ancho"><span>2</span><div><h3>Datos de la mascota</h3><p>Información mínima para identificarla.</p></div></div><label>Nombre de la mascota *<input name="paciente_nombre" required maxlength="100"></label><label>Especie *<select name="especie" required><option value="">Seleccionar</option><option>Canino</option><option>Felino</option><option>Ave</option><option>Otro</option></select></label><label>Raza<input name="raza" maxlength="100"></label><label>Sexo<select name="sexo"><option value="no_informado">No informado</option><option value="macho">Macho</option><option value="hembra">Hembra</option></select></label><label class="ancho">Alerta clínica importante<textarea name="alertas_clinicas" placeholder="Alergias, condición crítica u otra advertencia visible"></textarea></label><div class="acciones ancho"><button class="boton-grande">Guardar e iniciar atención</button><span class="ayuda-accion">Se creará la ficha y avanzarás directamente a la consulta.</span></div></form></section><?php vista_fin();}
function guardar_recepcion():void{post();$pdo=db();try{$pdo->beginTransaction();ejecutar('INSERT INTO tutores(nombre,identificacion,email,telefono) VALUES (?,NULLIF(?,""),NULLIF(?,""),?)',[requerido('tutor_nombre',160),trim($_POST['identificacion']??''),trim($_POST['email']??''),requerido('telefono',30)]);$tid=(int)$pdo->lastInsertId();$codigo='CV-'.str_pad((string)$tid,5,'0',STR_PAD_LEFT).'-'.strtoupper(substr(bin2hex(random_bytes(2)),0,4));ejecutar('INSERT INTO pacientes(codigo,tutor_id,nombre,especie,raza,sexo,alertas_clinicas) VALUES (?,?,?,?,NULLIF(?,""),?,NULLIF(?,""))',[$codigo,$tid,requerido('paciente_nombre',100),requerido('especie',60),trim($_POST['raza']??''),$_POST['sexo']??'no_informado',trim($_POST['alertas_clinicas']??'')]);$pid=(int)$pdo->lastInsertId();$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();abortar(422,'No fue posible registrar la llegada. Revisa los datos e inténtalo nuevamente.');}auditar('alta_recepcion','pacientes',$pid);flash('ok','Tutor y paciente registrados. Continúa con la atención clínica.');redirigir('atencion.form',['paciente_id'=>$pid]);}
function pagina_buscar():void{$q=trim((string)($_GET['q']??''));$like='%'.$q.'%';$ps=$q===''?[]:filas('SELECT p.id,p.codigo,p.nombre,p.especie,t.nombre tutor FROM pacientes p JOIN tutores t ON t.id=p.tutor_id WHERE p.nombre LIKE ? OR p.codigo LIKE ? OR t.nombre LIKE ? OR t.telefono LIKE ? ORDER BY p.nombre LIMIT 50',[$like,$like,$like,$like]);vista_inicio('Búsqueda');?><div class="cabecera"><h1>Resultados para “<?=e($q)?>”</h1></div><?php tabla_pacientes($ps);vista_fin();}
function pagina_tutores():void{$q=trim((string)($_GET['q']??''));$p=['%'.$q.'%'];$rs=filas('SELECT t.*,(SELECT COUNT(*) FROM pacientes p WHERE p.tutor_id=t.id) mascotas FROM tutores t WHERE t.nombre LIKE ? ORDER BY t.nombre LIMIT 100',$p);vista_inicio('Tutores');?><div class="cabecera"><h1>Tutores</h1><a class="boton" href="index.php?r=tutor.form">Nuevo tutor</a></div><form class="tarjeta"><input type="hidden" name="r" value="tutores"><label>Buscar<input name="q" value="<?=e($q)?>"></label></form><div class="tabla"><table><thead><tr><th>Nombre</th><th>Contacto</th><th>Mascotas</th><th></th></tr></thead><tbody><?php foreach($rs as $r):?><tr><td data-label="Nombre"><?=e($r['nombre'])?></td><td data-label="Contacto"><?=e($r['telefono']?:$r['email']?:'Sin contacto')?></td><td data-label="Mascotas"><?=(int)$r['mascotas']?></td><td><a href="index.php?r=tutor.form&amp;id=<?=$r['id']?>">Editar</a></td></tr><?php endforeach;?></tbody></table></div><?php vista_fin();}
function form_tutor():void{$r=isset($_GET['id'])?fila('SELECT * FROM tutores WHERE id=?',[id_get()]):[];vista_inicio($r?'Editar tutor':'Nuevo tutor');?><div class="cabecera"><h1><?=$r?'Editar tutor':'Nuevo tutor'?></h1></div><form class="tarjeta form-grid" action="index.php?r=tutor.guardar" method="post"><?=campo_csrf()?><input type="hidden" name="id" value="<?=e($r['id']??'')?>"><input type="hidden" name="version" value="<?=e($r['version']??1)?>"><?php foreach(['nombre'=>'Nombre *','identificacion'=>'RUT o identificación','email'=>'Correo','telefono'=>'Teléfono principal','telefono_alt'=>'Teléfono alternativo','direccion'=>'Dirección','sin_contacto_motivo'=>'Motivo si no posee contacto'] as $k=>$n):?><label><?=$n?><input name="<?=$k?>" value="<?=e($r[$k]??'')?>" <?=$k==='nombre'?'required':''?>></label><?php endforeach;?><label class="ancho">Observaciones<textarea name="observaciones"><?=e($r['observaciones']??'')?></textarea></label><div class="acciones ancho"><button>Guardar</button><a class="boton secundario" href="index.php?r=tutores">Cancelar</a></div></form><?php vista_fin();}
function guardar_tutor():void{post();$id=(int)($_POST['id']??0);$v=[requerido('nombre',160),trim($_POST['identificacion']??''),trim($_POST['email']??''),trim($_POST['telefono']??''),trim($_POST['telefono_alt']??''),trim($_POST['direccion']??''),trim($_POST['observaciones']??''),trim($_POST['sin_contacto_motivo']??'')];if($v[2]===''&&$v[3]===''&&$v[4]===''&&$v[7]==='')abortar(422,'Indica al menos un contacto o el motivo de su ausencia.');if($id){$v[]=$id;$v[]=(int)$_POST['version'];if(!ejecutar('UPDATE tutores SET nombre=?,identificacion=NULLIF(?,""),email=NULLIF(?,""),telefono=NULLIF(?,""),telefono_alt=NULLIF(?,""),direccion=NULLIF(?,""),observaciones=NULLIF(?,""),sin_contacto_motivo=NULLIF(?,""),version=version+1 WHERE id=? AND version=?',$v))abortar(409,'El tutor fue modificado por otra persona. Recarga la ficha.');}else{ejecutar('INSERT INTO tutores(nombre,identificacion,email,telefono,telefono_alt,direccion,observaciones,sin_contacto_motivo) VALUES (?,NULLIF(?,""),NULLIF(?,""),NULLIF(?,""),NULLIF(?,""),NULLIF(?,""),NULLIF(?,""),NULLIF(?,""))',$v);$id=(int)db()->lastInsertId();}auditar('guardar','tutores',$id);flash('ok','Tutor guardado.');redirigir('tutores');}
function tabla_pacientes(array $rs):void{if(!$rs){echo '<section class="tarjeta estado-vacio">No hay pacientes para mostrar.</section>';return;}?><div class="tabla"><table><thead><tr><th>Código</th><th>Paciente</th><th>Especie</th><th>Tutor</th><th></th></tr></thead><tbody><?php foreach($rs as $r):?><tr><td data-label="Código"><?=e($r['codigo'])?></td><td data-label="Paciente"><strong><?=e($r['nombre'])?></strong></td><td data-label="Especie"><?=e($r['especie'])?></td><td data-label="Tutor"><?=e($r['tutor'])?></td><td><a href="index.php?r=paciente.ficha&amp;id=<?=$r['id']?>">Ver ficha</a></td></tr><?php endforeach;?></tbody></table></div><?php }
function pagina_pacientes():void{$q=trim((string)($_GET['q']??''));$l='%'.$q.'%';$rs=filas('SELECT p.id,p.codigo,p.nombre,p.especie,t.nombre tutor FROM pacientes p JOIN tutores t ON t.id=p.tutor_id WHERE p.nombre LIKE ? OR p.codigo LIKE ? OR t.nombre LIKE ? ORDER BY p.nombre LIMIT 100',[$l,$l,$l]);vista_inicio('Pacientes');?><div class="cabecera"><h1>Pacientes</h1><a class="boton" href="index.php?r=paciente.form">Nuevo paciente</a></div><form class="tarjeta"><input type="hidden" name="r" value="pacientes"><label>Buscar<input name="q" value="<?=e($q)?>"></label></form><?php tabla_pacientes($rs);vista_fin();}
function form_paciente():void{$r=isset($_GET['id'])?fila('SELECT * FROM pacientes WHERE id=?',[id_get()]):[];$ts=filas('SELECT id,nombre,telefono FROM tutores WHERE activo=1 ORDER BY nombre');vista_inicio($r?'Editar paciente':'Nuevo paciente');?><div class="cabecera"><h1><?=$r?'Editar paciente':'Nuevo paciente'?></h1></div><form class="tarjeta form-grid" action="index.php?r=paciente.guardar" method="post"><?=campo_csrf()?><input type="hidden" name="id" value="<?=e($r['id']??'')?>"><input type="hidden" name="version" value="<?=e($r['version']??1)?>"><label>Tutor *<select name="tutor_id" required><option value="">Seleccionar</option><?php foreach($ts as $t):?><option value="<?=$t['id']?>" <?=($r['tutor_id']??'')==$t['id']?'selected':''?>><?=e($t['nombre'].' · '.$t['telefono'])?></option><?php endforeach;?></select></label><label>Código interno *<input name="codigo" required value="<?=e($r['codigo']??'')?>"></label><label>Nombre *<input name="nombre" required value="<?=e($r['nombre']??'')?>"></label><label>Especie *<input name="especie" required value="<?=e($r['especie']??'')?>"></label><label>Raza<input name="raza" value="<?=e($r['raza']??'')?>"></label><label>Sexo<select name="sexo"><?php foreach(['no_informado'=>'No informado','macho'=>'Macho','hembra'=>'Hembra'] as $v=>$n):?><option value="<?=$v?>" <?=($r['sexo']??'no_informado')===$v?'selected':''?>><?=$n?></option><?php endforeach;?></select></label><label>Fecha de nacimiento<input type="date" name="nacimiento" value="<?=e($r['nacimiento']??'')?>"></label><label>Edad estimada (meses)<input type="number" min="0" name="edad_estimada_meses" value="<?=e($r['edad_estimada_meses']??'')?>"></label><label>Microchip<input name="microchip" value="<?=e($r['microchip']??'')?>"></label><label>Estado<select name="estado"><?php foreach(['activo','inactivo','fallecido'] as $v):?><option <?=($r['estado']??'activo')===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label class="ancho">Antecedentes<textarea name="antecedentes"><?=e($r['antecedentes']??'')?></textarea></label><label class="ancho">Alertas clínicas<textarea name="alertas_clinicas"><?=e($r['alertas_clinicas']??'')?></textarea></label><div class="acciones ancho"><button>Guardar</button><a class="boton secundario" href="index.php?r=pacientes">Cancelar</a></div></form><?php vista_fin();}
function guardar_paciente():void{post();$id=(int)($_POST['id']??0);$p=[(int)$_POST['tutor_id'],requerido('codigo',30),requerido('nombre',100),requerido('especie',60),trim($_POST['raza']??''),$_POST['sexo']??'no_informado',trim($_POST['nacimiento']??''),trim($_POST['edad_estimada_meses']??''),trim($_POST['microchip']??''),trim($_POST['antecedentes']??''),trim($_POST['alertas_clinicas']??''),$_POST['estado']??'activo'];if(!$p[0]||!fila('SELECT id FROM tutores WHERE id=?',[$p[0]]))abortar(422,'Selecciona un tutor válido.');if($p[6]!==''&&$p[7]!=='')abortar(422,'Indica fecha de nacimiento o edad estimada, no ambas.');try{if($id){$p[]=$id;$p[]=(int)$_POST['version'];$n=ejecutar('UPDATE pacientes SET tutor_id=?,codigo=?,nombre=?,especie=?,raza=NULLIF(?,""),sexo=?,nacimiento=NULLIF(?,""),edad_estimada_meses=NULLIF(?,""),microchip=NULLIF(?,""),antecedentes=NULLIF(?,""),alertas_clinicas=NULLIF(?,""),estado=?,version=version+1 WHERE id=? AND version=?',$p);if(!$n)abortar(409,'La ficha fue modificada por otra persona.');}else{ejecutar('INSERT INTO pacientes(tutor_id,codigo,nombre,especie,raza,sexo,nacimiento,edad_estimada_meses,microchip,antecedentes,alertas_clinicas,estado) VALUES (?,?,?,?,NULLIF(?,""),?,NULLIF(?,""),NULLIF(?,""),NULLIF(?,""),NULLIF(?,""),NULLIF(?,""),?)',$p);$id=(int)db()->lastInsertId();}}catch(PDOException $e){abortar(422,'El código o microchip ya está registrado, o los datos no son válidos.');}auditar('guardar','pacientes',$id);flash('ok','Paciente guardado.');redirigir('paciente.ficha',['id'=>$id]);}
function ficha_paciente():void{$id=id_get();$p=fila('SELECT p.*,t.nombre tutor,t.telefono,t.email FROM pacientes p JOIN tutores t ON t.id=p.tutor_id WHERE p.id=?',[$id]);if(!$p)abortar(404,'Paciente no encontrado.');$as=filas('SELECT a.*,u.nombre profesional FROM atenciones a JOIN usuarios u ON u.id=a.responsable_id WHERE paciente_id=? ORDER BY fecha_clinica DESC',[$id]);vista_inicio($p['nombre']);?><div class="cabecera"><div><h1><?=e($p['nombre'])?></h1><p><?=e($p['codigo'].' · '.$p['especie'].' · Tutor: '.$p['tutor'])?></p></div><div class="acciones"><a class="boton" href="index.php?r=atencion.form&amp;paciente_id=<?=$id?>">Nueva atención</a><a class="boton secundario" href="index.php?r=paciente.form&amp;id=<?=$id?>">Editar</a></div></div><?php if($p['alertas_clinicas']):?><div class="alerta aviso"><strong>Alerta clínica:</strong> <?=nl2br(e($p['alertas_clinicas']))?></div><?php endif;?><section class="tarjeta"><h2>Resumen</h2><p><strong>Tutor:</strong> <?=e($p['tutor'])?> · <?=e($p['telefono']?:$p['email']?:'sin contacto')?></p><p><strong>Antecedentes:</strong> <?=nl2br(e($p['antecedentes']?:'Sin antecedentes registrados'))?></p></section><h2>Historial clínico</h2><?php if(!$as):?><div class="tarjeta estado-vacio">Aún no hay atenciones.</div><?php endif;foreach($as as $a):?><article class="tarjeta"><span class="etiqueta"><?=e($a['estado'])?></span><h3><?=e(utc_a_local($a['fecha_clinica']))?> · <?=e($a['motivo'])?></h3><p><?=e($a['diagnostico']?:'Diagnóstico pendiente')?> · Profesional: <?=e($a['profesional'])?></p><a href="index.php?r=atencion.detalle&amp;id=<?=$a['id']?>">Ver atención</a></article><?php endforeach;vista_fin();}
function pagina_atenciones():void{$rs=filas('SELECT a.id,a.fecha_clinica,a.motivo,a.estado,p.nombre paciente,u.nombre profesional FROM atenciones a JOIN pacientes p ON p.id=a.paciente_id JOIN usuarios u ON u.id=a.responsable_id ORDER BY a.fecha_clinica DESC LIMIT 100');vista_inicio('Atenciones');?><div class="cabecera"><h1>Atenciones</h1><a class="boton" href="index.php?r=atencion.form">Nueva atención</a></div><div class="tabla"><table><thead><tr><th>Fecha</th><th>Paciente</th><th>Motivo</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($rs as $r):?><tr><td data-label="Fecha"><?=e(utc_a_local($r['fecha_clinica']))?></td><td data-label="Paciente"><?=e($r['paciente'])?></td><td data-label="Motivo"><?=e($r['motivo'])?></td><td data-label="Estado"><?=e($r['estado'])?></td><td><a href="index.php?r=atencion.detalle&amp;id=<?=$r['id']?>">Ver</a></td></tr><?php endforeach;?></tbody></table></div><?php vista_fin();}
function form_atencion():void{$ps=filas('SELECT id,codigo,nombre FROM pacientes WHERE estado="activo" ORDER BY nombre');$us=filas('SELECT id,nombre FROM usuarios WHERE activo=1 ORDER BY nombre');$pid=(int)($_GET['paciente_id']??0);$seleccionado=$pid?fila('SELECT p.nombre,p.codigo,p.especie,t.nombre tutor,p.alertas_clinicas FROM pacientes p JOIN tutores t ON t.id=p.tutor_id WHERE p.id=?',[$pid]):false;vista_inicio('Nueva atención');?><nav class="pasos" aria-label="Proceso de atención"><span><b>1</b> Recepción</span><span class="activo"><b>2</b> Atención clínica</span><span><b>3</b> Servicios e insumos</span><span><b>4</b> Cobro</span></nav><div class="cabecera"><div><span class="sobrelinea">CONSULTA CLÍNICA</span><h1>Nueva atención</h1><p>Registra lo esencial durante la consulta. Puedes guardar como borrador.</p></div></div><?php if($seleccionado):?><section class="contexto-paciente"><div class="avatar-mascota"><?=e(mb_substr($seleccionado['nombre'],0,1))?></div><div><strong><?=e($seleccionado['nombre'])?></strong><div><?=e($seleccionado['codigo'].' · '.$seleccionado['especie'].' · Tutor: '.$seleccionado['tutor'])?></div><?php if($seleccionado['alertas_clinicas']):?><span class="aviso-clinico">⚠ <?=e($seleccionado['alertas_clinicas'])?></span><?php endif;?></div></section><?php endif;?><form class="tarjeta form-grid" action="index.php?r=atencion.guardar" method="post"><?=campo_csrf()?><label>Paciente *<select name="paciente_id" required><option value="">Seleccionar</option><?php foreach($ps as $p):?><option value="<?=$p['id']?>" <?=$pid===$p['id']?'selected':''?>><?=e($p['nombre'].' · '.$p['codigo'])?></option><?php endforeach;?></select></label><label>Profesional responsable *<select name="responsable_id" required><?php foreach($us as $u):?><option value="<?=$u['id']?>" <?=$u['id']==usuario()['id']?'selected':''?>><?=e($u['nombre'])?></option><?php endforeach;?></select></label><label>Fecha y hora *<input type="datetime-local" name="fecha_clinica" required value="<?=date('Y-m-d\TH:i')?>"></label><label>Peso (kg)<input type="number" name="peso" min="0" step="0.001"></label><label class="ancho">Motivo de consulta *<input name="motivo" required maxlength="500" placeholder="¿Por qué consulta hoy?"></label><?php foreach(['historia'=>'Historia clínica','examen'=>'Examen y observaciones','diagnostico'=>'Diagnóstico','tratamiento'=>'Tratamiento','indicaciones'=>'Indicaciones para el tutor'] as $k=>$n):?><label class="ancho"><?=$n?><textarea name="<?=$k?>"></textarea></label><?php endforeach;?><label>Próximo control<input type="date" name="proximo_control"></label><label>Estado<select name="estado"><option value="borrador">Guardar borrador</option><option value="finalizada">Finalizar atención</option></select></label><div class="acciones ancho"><button class="boton-grande">Guardar y continuar a servicios</button><a class="boton secundario" href="index.php?r=recepcion">Volver a recepción</a></div></form><?php vista_fin();}
function guardar_atencion():void{post();$estado=$_POST['estado']??'borrador';$hist=trim($_POST['historia']??'');if($estado==='finalizada'&&$hist==='')abortar(422,'La historia clínica es obligatoria para finalizar.');$local=new DateTimeImmutable(requerido('fecha_clinica'),new DateTimeZone($GLOBALS['config']['timezone']));$fecha=$local->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');$p=[(int)$_POST['paciente_id'],usuario()['id'],(int)$_POST['responsable_id'],$fecha,requerido('motivo',500),$hist,trim($_POST['examen']??''),trim($_POST['peso']??''),trim($_POST['diagnostico']??''),trim($_POST['tratamiento']??''),trim($_POST['indicaciones']??''),trim($_POST['proximo_control']??''),$estado];ejecutar('INSERT INTO atenciones(paciente_id,autor_id,responsable_id,fecha_clinica,motivo,historia,examen,peso,diagnostico,tratamiento,indicaciones,proximo_control,estado) VALUES (?,?,?,?,?,NULLIF(?,""),NULLIF(?,""),NULLIF(?,""),NULLIF(?,""),NULLIF(?,""),NULLIF(?,""),NULLIF(?,""),?)',$p);$id=(int)db()->lastInsertId();ejecutar('INSERT INTO cuentas(atencion_id) VALUES (?)',[$id]);auditar('crear','atenciones',$id);flash('ok','Atención guardada.');redirigir('atencion.detalle',['id'=>$id]);}
function detalle_atencion():void{$id=id_get();$a=fila('SELECT a.*,p.nombre paciente,p.id paciente_id,u.nombre profesional,c.id cuenta_id FROM atenciones a JOIN pacientes p ON p.id=a.paciente_id JOIN usuarios u ON u.id=a.responsable_id JOIN cuentas c ON c.atencion_id=a.id WHERE a.id=?',[$id]);if(!$a)abortar(404,'Atención no encontrada.');$ac=filas('SELECT x.*,u.nombre autor FROM aclaraciones_atencion x JOIN usuarios u ON u.id=x.autor_id WHERE atencion_id=? ORDER BY creado_en',[$id]);vista_inicio('Atención');?><nav class="pasos" aria-label="Proceso de atención"><span><b>1</b> Recepción</span><span class="activo"><b>2</b> Atención clínica</span><span><b>3</b> Servicios e insumos</span><span><b>4</b> Cobro</span></nav><div class="cabecera"><div><span class="sobrelinea">ATENCIÓN GUARDADA</span><h1><?=e($a['paciente'])?></h1><p><?=e(utc_a_local($a['fecha_clinica']))?> · <?=e($a['estado'])?></p></div><a class="boton boton-grande" href="index.php?r=cobro.detalle&amp;id=<?=$a['cuenta_id']?>">Agregar servicios y cobrar →</a></div><section class="tarjeta"><?php foreach(['Motivo'=>'motivo','Historia clínica'=>'historia','Examen'=>'examen','Diagnóstico'=>'diagnostico','Tratamiento'=>'tratamiento','Indicaciones'=>'indicaciones'] as $n=>$k):?><h3><?=$n?></h3><p><?=nl2br(e($a[$k]?:'Sin registro'))?></p><?php endforeach;?></section><?php foreach($ac as $x):?><article class="tarjeta"><h3>Aclaración · <?=e(utc_a_local($x['creado_en']))?></h3><p><?=nl2br(e($x['texto']))?></p><small><?=e($x['autor'])?></small></article><?php endforeach;?><form class="tarjeta" action="index.php?r=atencion.aclarar&amp;id=<?=$id?>" method="post"><?=campo_csrf()?><label>Agregar aclaración<textarea name="texto" required></textarea></label><button>Guardar aclaración</button></form><?php vista_fin();}
function aclarar_atencion():void{post();$id=id_get();ejecutar('INSERT INTO aclaraciones_atencion(atencion_id,texto,autor_id) VALUES (?,?,?)',[$id,requerido('texto',5000),usuario()['id']]);auditar('aclarar','atenciones',$id);flash('ok','Aclaración agregada.');redirigir('atencion.detalle',['id'=>$id]);}
function pagina_servicios():void{$rs=filas('SELECT * FROM servicios ORDER BY activo DESC,nombre');vista_inicio('Servicios');?><div class="cabecera"><h1>Servicios</h1></div><form class="tarjeta form-grid" action="index.php?r=servicio.guardar" method="post"><?=campo_csrf()?><label>Nombre<input name="nombre" required></label><label>Categoría<input name="categoria"></label><label>Tarifa CLP<input type="number" min="0" name="tarifa" required></label><div class="acciones"><button>Crear servicio</button></div></form><div class="tabla"><table><thead><tr><th>Servicio</th><th>Categoría</th><th>Tarifa</th></tr></thead><tbody><?php foreach($rs as $r):?><tr><td><?=e($r['nombre'])?></td><td><?=e($r['categoria'])?></td><td><?=clp($r['tarifa'])?></td></tr><?php endforeach;?></tbody></table></div><?php vista_fin();}
function guardar_servicio():void{post();ejecutar('INSERT INTO servicios(nombre,categoria,tarifa) VALUES (?,?,?)',[requerido('nombre',140),trim($_POST['categoria']??''),max(0,(int)$_POST['tarifa'])]);auditar('crear','servicios',db()->lastInsertId());flash('ok','Servicio creado.');redirigir('servicios');}
function saldo_cuenta(int $id):array{$c=fila('SELECT COALESCE(SUM(cantidad*precio_unitario),0) bruto FROM cargos WHERE cuenta_id=? AND estado="vigente"',[$id]);$d=fila('SELECT COALESCE(SUM(d.importe),0) total FROM descuentos d JOIN cargos c ON c.id=d.cargo_id WHERE c.cuenta_id=? AND c.estado="vigente" AND d.estado="aprobado"',[$id]);$p=fila('SELECT COALESCE(SUM(p.importe),0)-COALESCE((SELECT SUM(d.importe) FROM devoluciones d JOIN pagos px ON px.id=d.pago_id WHERE px.cuenta_id=?),0) total FROM pagos p LEFT JOIN anulaciones_pago a ON a.pago_id=p.id WHERE p.cuenta_id=? AND a.id IS NULL',[$id,$id]);$total=max(0,(int)$c['bruto']-(int)$d['total']);return ['bruto'=>(int)$c['bruto'],'descuento'=>(int)$d['total'],'total'=>$total,'pagado'=>(int)$p['total'],'saldo'=>$total-(int)$p['total']];}
function pagina_cobros():void{$rs=filas('SELECT c.id,p.nombre paciente,a.fecha_clinica FROM cuentas c JOIN atenciones a ON a.id=c.atencion_id JOIN pacientes p ON p.id=a.paciente_id ORDER BY a.fecha_clinica DESC LIMIT 100');vista_inicio('Cobros');?><div class="cabecera"><h1>Cobros</h1></div><div class="tabla"><table><thead><tr><th>Paciente</th><th>Fecha</th><th>Saldo</th><th></th></tr></thead><tbody><?php foreach($rs as $r):$s=saldo_cuenta((int)$r['id']);?><tr><td><?=e($r['paciente'])?></td><td><?=e(utc_a_local($r['fecha_clinica']))?></td><td><?=clp($s['saldo'])?></td><td><a href="index.php?r=cobro.detalle&amp;id=<?=$r['id']?>">Abrir</a></td></tr><?php endforeach;?></tbody></table></div><?php vista_fin();}
function detalle_cobro():void{$id=id_get();$c=fila('SELECT c.*,p.nombre paciente,a.id atencion_id FROM cuentas c JOIN atenciones a ON a.id=c.atencion_id JOIN pacientes p ON p.id=a.paciente_id WHERE c.id=?',[$id]);if(!$c)abortar(404,'Cuenta no encontrada.');$cs=filas('SELECT * FROM cargos WHERE cuenta_id=? ORDER BY id',[$id]);$ps=filas('SELECT * FROM pagos WHERE cuenta_id=? ORDER BY fecha',[$id]);$ss=filas('SELECT id,nombre,tarifa FROM servicios WHERE activo=1 ORDER BY nombre');$s=saldo_cuenta($id);vista_inicio('Cobro');?><div class="cabecera"><div><h1>Cobro · <?=e($c['paciente'])?></h1><p>Saldo: <strong><?=clp($s['saldo'])?></strong></p></div></div><div class="rejilla"><article class="tarjeta metrica">Total<strong><?=clp($s['total'])?></strong></article><article class="tarjeta metrica">Pagado<strong><?=clp($s['pagado'])?></strong></article><article class="tarjeta metrica">Saldo<strong><?=clp($s['saldo'])?></strong></article></div><section class="tarjeta"><h2>Cargos</h2><?php foreach($cs as $x):?><p><?=e($x['descripcion'])?> · <?=e($x['cantidad'])?> × <?=clp($x['precio_unitario'])?></p><?php endforeach;?><form class="form-grid" action="index.php?r=cargo.guardar&amp;id=<?=$id?>" method="post"><?=campo_csrf()?><label>Servicio<select name="servicio_id" required><?php foreach($ss as $x):?><option value="<?=$x['id']?>"><?=e($x['nombre'])?> · <?=clp($x['tarifa'])?></option><?php endforeach;?></select></label><label>Cantidad<input type="number" name="cantidad" min="0.01" step="0.01" value="1" required></label><div class="acciones"><button>Agregar cargo</button></div></form></section><section class="tarjeta"><h2>Pagos</h2><?php foreach($ps as $x):?><p><?=clp($x['importe'])?> · <?=e($x['medio'])?> · <?=e(utc_a_local($x['fecha']))?></p><?php endforeach;?><form class="form-grid" action="index.php?r=pago.guardar&amp;id=<?=$id?>" method="post"><?=campo_csrf()?><input type="hidden" name="operacion_id" value="<?=operacion_id()?>"><label>Importe<input type="number" name="importe" min="1" max="<?=$s['saldo']?>" required></label><label>Medio<select name="medio"><option>efectivo</option><option>transferencia</option><option>tarjeta</option></select></label><label>Referencia<input name="referencia"></label><div class="acciones"><button <?=$s['saldo']<=0?'disabled':''?>>Registrar pago</button></div></form><p><small>Comprobante interno: no constituye boleta ni factura tributaria.</small></p></section><?php vista_fin();}
function guardar_cargo():void{post();$id=id_get();$serv=fila('SELECT * FROM servicios WHERE id=? AND activo=1',[(int)$_POST['servicio_id']]);if(!$serv)abortar(422,'Servicio inválido.');ejecutar('INSERT INTO cargos(cuenta_id,servicio_id,descripcion,cantidad,precio_unitario) VALUES (?,?,?,?,?)',[$id,$serv['id'],$serv['nombre'],(float)$_POST['cantidad'],$serv['tarifa']]);auditar('crear','cargos',db()->lastInsertId());redirigir('cobro.detalle',['id'=>$id]);}
function guardar_pago():void{post();$id=id_get();$m=$_POST['medio']??'';$ref=trim($_POST['referencia']??'');if(!in_array($m,['efectivo','transferencia','tarjeta'],true)||($m!=='efectivo'&&$ref===''))abortar(422,'Medio o referencia inválidos.');$pdo=db();try{$pdo->beginTransaction();$st=$pdo->prepare('SELECT id FROM cuentas WHERE id=? FOR UPDATE');$st->execute([$id]);$s=saldo_cuenta($id);$importe=(int)$_POST['importe'];if($importe<1||$importe>$s['saldo'])throw new RuntimeException('El importe supera el saldo disponible.');ejecutar('INSERT INTO pagos(cuenta_id,importe,medio,fecha,referencia,autor_id,operacion_id) VALUES (?,?,?,UTC_TIMESTAMP(),NULLIF(?,""),?,?)',[$id,$importe,$m,$ref,usuario()['id'],requerido('operacion_id',32)]);if($importe===$s['saldo'])ejecutar('UPDATE cuentas SET estado="pagada",version=version+1 WHERE id=?',[$id]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();abortar(422,$e instanceof RuntimeException?$e->getMessage():'El pago ya fue procesado o no pudo registrarse.');}auditar('crear','pagos',db()->lastInsertId());flash('ok','Pago registrado manualmente.');redirigir('cobro.detalle',['id'=>$id]);}
function guardar_descuento():void{post();$cargo=(int)$_POST['cargo_id'];$c=fila('SELECT cantidad*precio_unitario total FROM cargos WHERE id=?',[$cargo]);$i=(int)$_POST['importe'];if(!$c||$i<1||$i>(int)$c['total'])abortar(422,'Descuento inválido.');$estado=es_superadmin()?'aprobado':'pendiente';ejecutar('INSERT INTO descuentos(cargo_id,importe,tipo,motivo,estado,solicitante_id,autorizante_id,autorizado_en) VALUES (?,?,?,?,?,?,?,?)',[$cargo,$i,$i===(int)$c['total']?'gratuidad':'parcial',requerido('motivo',500),$estado,usuario()['id'],es_superadmin()?usuario()['id']:null,es_superadmin()?gmdate('Y-m-d H:i:s'):null]);auditar('crear','descuentos',db()->lastInsertId());flash('ok',$estado==='aprobado'?'Descuento aprobado.':'Descuento solicitado.');redirigir('cobros');}
function pagina_stock():void{$rs=filas('SELECT p.*,COALESCE(SUM(l.saldo_base),0) fisico,COALESCE(SUM(CASE WHEN l.vencimiento IS NULL OR l.vencimiento>=CURRENT_DATE THEN l.saldo_base ELSE 0 END),0) utilizable FROM productos p LEFT JOIN lotes l ON l.producto_id=p.id GROUP BY p.id ORDER BY p.nombre');vista_inicio('Stock');?><div class="cabecera"><h1>Stock</h1><?php if(es_superadmin()):?><a class="boton" href="index.php?r=producto.form">Nuevo producto</a><?php endif;?></div><div class="tabla"><table><thead><tr><th>Producto</th><th>Físico</th><th>Utilizable</th><th>Mínimo</th></tr></thead><tbody><?php foreach($rs as $r):?><tr><td><?=e($r['nombre'])?></td><td><?=e($r['fisico'].' '.$r['unidad_base'])?></td><td><?=e($r['utilizable'].' '.$r['unidad_base'])?> <?=$r['utilizable']<=$r['stock_minimo']?'<span class="etiqueta pendiente">Alerta</span>':''?></td><td><?=e($r['stock_minimo'])?></td></tr><?php endforeach;?></tbody></table></div><?php vista_fin();}
function form_producto():void{vista_inicio('Nuevo producto');?><div class="cabecera"><h1>Nuevo producto</h1></div><form class="tarjeta form-grid" method="post" action="index.php?r=producto.guardar"><?=campo_csrf()?><?php foreach(['codigo'=>'Código','nombre'=>'Nombre','categoria'=>'Categoría','unidad_base'=>'Unidad base','presentacion'=>'Presentación'] as $k=>$n):?><label><?=$n?><input name="<?=$k?>" required></label><?php endforeach;?><label>Factor de conversión<input type="number" step="0.0001" min="0.0001" name="factor_conversion" value="1" required></label><label>Stock mínimo<input type="number" step="0.0001" min="0" name="stock_minimo" value="0" required></label><div class="acciones ancho"><button>Guardar</button></div></form><?php vista_fin();}
function guardar_producto():void{post();ejecutar('INSERT INTO productos(codigo,nombre,categoria,unidad_base,presentacion,factor_conversion,stock_minimo) VALUES (?,?,?,?,?,?,?)',[requerido('codigo',40),requerido('nombre',150),trim($_POST['categoria']??''),requerido('unidad_base',30),requerido('presentacion',80),(float)$_POST['factor_conversion'],(float)$_POST['stock_minimo']]);auditar('crear','productos',db()->lastInsertId());flash('ok','Producto creado.');redirigir('stock');}
function guardar_entrada():void{post();$producto=(int)($_POST['producto_id']??0);$cantidad=(float)($_POST['cantidad']??0);$costo=(float)($_POST['costo_unitario_base']??0);$vencimiento=trim((string)($_POST['vencimiento']??''));if(!fila('SELECT id FROM productos WHERE id=? AND activo=1',[$producto])||$cantidad<=0||$costo<0)abortar(422,'Producto, cantidad o costo inválido.');if($vencimiento!==''&&!DateTimeImmutable::createFromFormat('Y-m-d',$vencimiento))abortar(422,'La fecha de vencimiento no es válida.');$pdo=db();try{$pdo->beginTransaction();ejecutar('INSERT INTO lotes(producto_id,codigo_lote,vencimiento,saldo_base,costo_unitario_base) VALUES (?,NULLIF(?,""),NULLIF(?,""),?,?)',[$producto,trim((string)($_POST['codigo_lote']??'')),$vencimiento,$cantidad,$costo]);$lote=(int)$pdo->lastInsertId();ejecutar('INSERT INTO movimientos_stock(lote_id,tipo,cantidad,costo_historico,motivo,autor_id,operacion_id) VALUES (?,"entrada",?,?,?,?,?)',[$lote,$cantidad,$costo,trim((string)($_POST['motivo']??'Entrada de inventario')),usuario()['id'],requerido('operacion_id',32)]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();abortar(422,'No fue posible registrar la entrada. Verifica los datos e inténtalo nuevamente.');}auditar('entrada','stock',$lote);flash('ok','Entrada de stock registrada.');redirigir('producto.form',['id'=>$producto]);}
function guardar_consumo():void{post();$lote=(int)($_POST['lote_id']??0);$q=(float)($_POST['cantidad']??0);$atencion=(int)($_POST['atencion_id']??0);$pdo=db();try{$pdo->beginTransaction();$l=fila('SELECT * FROM lotes WHERE id=? FOR UPDATE',[$lote]);if(!$l||$q<=0||$q>(float)$l['saldo_base']||($l['vencimiento']&&$l['vencimiento']<date('Y-m-d')))throw new RuntimeException('Lote vencido o stock insuficiente.');if($atencion&&!fila('SELECT id FROM atenciones WHERE id=?',[$atencion]))throw new RuntimeException('La atención indicada no existe.');ejecutar('UPDATE lotes SET saldo_base=saldo_base-? WHERE id=?',[$q,$lote]);ejecutar('INSERT INTO movimientos_stock(lote_id,atencion_id,tipo,cantidad,costo_historico,motivo,autor_id,operacion_id) VALUES (?,NULLIF(?,0),"consumo",?,?,?,?,?)',[$lote,$atencion,-$q,$l['costo_unitario_base'],trim((string)($_POST['motivo']??'Consumo clínico')),usuario()['id'],requerido('operacion_id',32)]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();abortar(422,$e->getMessage());}auditar('consumo','stock',$lote);flash('ok','Consumo de stock registrado.');redirigir('producto.form',['id'=>(int)$l['producto_id']]);}
function pagina_finanzas():void{$desde=$_GET['desde']??date('Y-m-01');$hasta=$_GET['hasta']??date('Y-m-d');$p=[$desde.' 00:00:00',$hasta.' 23:59:59'];$pag=(int)fila('SELECT COALESCE(SUM(importe),0) n FROM pagos WHERE fecha BETWEEN ? AND ?',$p)['n'];$gas=(int)fila('SELECT COALESCE(SUM(importe),0) n FROM movimientos_financieros WHERE tipo="gasto" AND estado="vigente" AND fecha BETWEEN ? AND ?',$p)['n'];vista_inicio('Finanzas');?><div class="cabecera"><h1>Finanzas</h1></div><div class="rejilla"><article class="tarjeta metrica">Cobros recibidos<strong><?=clp($pag)?></strong></article><article class="tarjeta metrica">Gastos<strong><?=clp($gas)?></strong></article><article class="tarjeta metrica">Flujo<strong><?=clp($pag-$gas)?></strong></article></div><form class="tarjeta form-grid" action="index.php?r=finanza.guardar" method="post"><?=campo_csrf()?><label>Tipo<select name="tipo"><option value="gasto">Gasto</option><option value="ingreso">Otro ingreso</option></select></label><label>Categoría<input name="categoria" required></label><label>Descripción<input name="descripcion" required></label><label>Importe<input type="number" name="importe" min="1" required></label><label>Medio<select name="medio"><option>efectivo</option><option>transferencia</option><option>tarjeta</option></select></label><button>Registrar movimiento</button></form><?php vista_fin();}
function guardar_finanza():void{post();ejecutar('INSERT INTO movimientos_financieros(tipo,categoria,descripcion,importe,medio,fecha,responsable_id,operacion_id) VALUES (?,?,?,?,?,UTC_TIMESTAMP(),?,?)',[$_POST['tipo'],requerido('categoria',100),requerido('descripcion',255),(int)$_POST['importe'],$_POST['medio'],usuario()['id'],operacion_id()]);auditar('crear','movimientos_financieros',db()->lastInsertId());redirigir('finanzas');}
function pagina_usuarios():void{$rs=filas('SELECT id,nombre,email,rol,activo,ultimo_acceso FROM usuarios ORDER BY nombre');vista_inicio('Usuarios');?><div class="cabecera"><h1>Usuarios</h1><a class="boton" href="index.php?r=usuario.form">Nuevo usuario</a></div><div class="tabla"><table><thead><tr><th>Nombre</th><th>Correo</th><th>Rol</th><th>Último acceso</th></tr></thead><tbody><?php foreach($rs as $r):?><tr><td><?=e($r['nombre'])?></td><td><?=e($r['email'])?></td><td><?=e($r['rol'])?></td><td><?=e(utc_a_local($r['ultimo_acceso']))?></td></tr><?php endforeach;?></tbody></table></div><?php vista_fin();}
function form_usuario():void{vista_inicio('Nuevo usuario');?><div class="cabecera"><h1>Nuevo usuario</h1></div><form class="tarjeta form-grid" action="index.php?r=usuario.guardar" method="post"><?=campo_csrf()?><label>Nombre<input name="nombre" required></label><label>Correo<input type="email" name="email" required></label><label>Rol<select name="rol"><option value="administrador">Administrador</option><option value="superadministrador">Superadministrador</option></select></label><label>Contraseña inicial<input type="password" name="password" minlength="12" required></label><button>Crear usuario</button></form><?php vista_fin();}
function guardar_usuario():void{post();$pass=requerido('password',200);if(mb_strlen($pass)<12)abortar(422,'La contraseña debe tener al menos 12 caracteres.');ejecutar('INSERT INTO usuarios(nombre,email,password_hash,rol) VALUES (?,?,?,?)',[requerido('nombre',120),mb_strtolower(requerido('email',190)),password_hash($pass,PASSWORD_DEFAULT),$_POST['rol']==='superadministrador'?'superadministrador':'administrador']);auditar('crear','usuarios',db()->lastInsertId());flash('ok','Usuario creado.');redirigir('usuarios');}
function pagina_configuracion():void{$rs=filas('SELECT * FROM configuracion ORDER BY clave');vista_inicio('Configuración');?><div class="cabecera"><h1>Configuración</h1></div><form class="tarjeta" action="index.php?r=configuracion.guardar" method="post"><?=campo_csrf()?><?php foreach($rs as $r):?><label><?=e($r['clave'])?><input name="valor[<?=e($r['clave'])?>]" value="<?=e($r['valor'])?>"></label><?php endforeach;?><button>Guardar configuración</button></form><?php vista_fin();}
function guardar_configuracion():void{post();foreach($_POST['valor']??[] as $k=>$v)ejecutar('UPDATE configuracion SET valor=? WHERE clave=?',[(string)$v,(string)$k]);auditar('actualizar','configuracion');flash('ok','Configuración guardada.');redirigir('configuracion');}
function pagina_auditoria():void{$rs=filas('SELECT a.*,u.nombre usuario FROM auditoria a LEFT JOIN usuarios u ON u.id=a.usuario_id ORDER BY a.creado_en DESC LIMIT 200');vista_inicio('Auditoría');?><div class="cabecera"><h1>Auditoría</h1></div><div class="tabla"><table><thead><tr><th>Fecha</th><th>Usuario</th><th>Acción</th><th>Entidad</th></tr></thead><tbody><?php foreach($rs as $r):?><tr><td><?=e(utc_a_local($r['creado_en']))?></td><td><?=e($r['usuario']?:'Sistema')?></td><td><?=e($r['accion'])?></td><td><?=e($r['entidad'].' #'.$r['entidad_id'])?></td></tr><?php endforeach;?></tbody></table></div><?php vista_fin();}
function guardar_recepcion_con_foto():void{post();$pdo=db();try{$pdo->beginTransaction();ejecutar('INSERT INTO tutores(nombre,identificacion,email,telefono) VALUES (?,NULLIF(?,""),NULLIF(?,""),?)',[requerido('tutor_nombre',160),trim($_POST['identificacion']??''),trim($_POST['email']??''),requerido('telefono',30)]);$tid=(int)$pdo->lastInsertId();$codigo='CV-'.str_pad((string)$tid,5,'0',STR_PAD_LEFT).'-'.strtoupper(substr(bin2hex(random_bytes(2)),0,4));ejecutar('INSERT INTO pacientes(codigo,tutor_id,nombre,especie,raza,sexo,alertas_clinicas) VALUES (?,?,?,?,NULLIF(?,""),?,NULLIF(?,""))',[$codigo,$tid,requerido('paciente_nombre',100),requerido('especie',60),trim($_POST['raza']??''),$_POST['sexo']??'no_informado',trim($_POST['alertas_clinicas']??'')]);$pid=(int)$pdo->lastInsertId();guardar_foto_paciente($pid);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();abortar(422,'No fue posible registrar la llegada o la fotografía. Revisa el archivo y los datos.');}auditar('alta_recepcion','pacientes',$pid);flash('ok','Tutor y paciente registrados. Continúa con la atención clínica.');redirigir('atencion.form',['paciente_id'=>$pid]);}
function guardar_paciente_con_foto():void{post();$id=(int)($_POST['id']??0);$p=[(int)$_POST['tutor_id'],requerido('codigo',30),requerido('nombre',100),requerido('especie',60),trim($_POST['raza']??''),$_POST['sexo']??'no_informado',trim($_POST['nacimiento']??''),trim($_POST['edad_estimada_meses']??''),trim($_POST['microchip']??''),trim($_POST['antecedentes']??''),trim($_POST['alertas_clinicas']??''),$_POST['estado']??'activo'];if(!$p[0]||!fila('SELECT id FROM tutores WHERE id=?',[$p[0]]))abortar(422,'Selecciona un tutor válido.');if($p[6]!==''&&$p[7]!=='')abortar(422,'Indica fecha de nacimiento o edad estimada, no ambas.');try{if($id){$p[]=$id;$p[]=(int)$_POST['version'];if(!ejecutar('UPDATE pacientes SET tutor_id=?,codigo=?,nombre=?,especie=?,raza=NULLIF(?,""),sexo=?,nacimiento=NULLIF(?,""),edad_estimada_meses=NULLIF(?,""),microchip=NULLIF(?,""),antecedentes=NULLIF(?,""),alertas_clinicas=NULLIF(?,""),estado=?,version=version+1 WHERE id=? AND version=?',$p))abortar(409,'La ficha fue modificada por otra persona.');}else{ejecutar('INSERT INTO pacientes(tutor_id,codigo,nombre,especie,raza,sexo,nacimiento,edad_estimada_meses,microchip,antecedentes,alertas_clinicas,estado) VALUES (?,?,?,?,NULLIF(?,""),?,NULLIF(?,""),NULLIF(?,""),NULLIF(?,""),NULLIF(?,""),NULLIF(?,""),?)',$p);$id=(int)db()->lastInsertId();}guardar_foto_paciente($id);}catch(PDOException $e){abortar(422,'El código, microchip o fotografía no son válidos.');}auditar('guardar','pacientes',$id);flash('ok','Paciente guardado.');redirigir('paciente.ficha',['id'=>$id]);}
function pagina_stock_mejorada():void{$f=$_GET['filtro']??'todos';$q=trim((string)($_GET['q']??''));$rs=filas('SELECT p.*,COALESCE(SUM(l.saldo_base),0) fisico,COALESCE(SUM(CASE WHEN l.vencimiento IS NULL OR l.vencimiento>=CURRENT_DATE THEN l.saldo_base ELSE 0 END),0) utilizable,MIN(CASE WHEN l.saldo_base>0 THEN l.vencimiento END) proximo_vencimiento FROM productos p LEFT JOIN lotes l ON l.producto_id=p.id WHERE p.activo=1 AND (p.nombre LIKE ? OR p.codigo LIKE ?) GROUP BY p.id ORDER BY p.nombre',['%'.$q.'%','%'.$q.'%']);$rs=array_values(array_filter($rs,fn($r)=>$f==='todos'||($f==='bajo'&&$r['alerta_activa']&&(float)$r['utilizable']<=(float)$r['stock_minimo'])||($f==='agotado'&&(float)$r['utilizable']<=0)));$alertas=count(array_filter($rs,fn($r)=>$r['alerta_activa']&&(float)$r['utilizable']<=(float)$r['stock_minimo']));vista_inicio('Stock');?><div class="cabecera"><div><span class="sobrelinea">INVENTARIO</span><h1>Stock y medicamentos</h1><p>Las alertas se calculan sobre existencias utilizables, excluyendo lotes vencidos.</p></div><?php if(es_superadmin()):?><a class="boton" href="index.php?r=producto.form">Nuevo producto</a><?php endif;?></div><div class="rejilla resumen-stock"><a class="tarjeta metrica" href="index.php?r=stock"><span>Productos</span><strong><?=count($rs)?></strong></a><a class="tarjeta metrica alerta-stock" href="index.php?r=stock&amp;filtro=bajo"><span>🔔 Bajo mínimo</span><strong><?=$alertas?></strong></a></div><form class="tarjeta filtros-inline" method="get"><input type="hidden" name="r" value="stock"><label>Buscar<input name="q" value="<?=e($q)?>" placeholder="Producto o código"></label><label>Estado<select name="filtro"><option value="todos">Todos</option><option value="bajo" <?=$f==='bajo'?'selected':''?>>Bajo mínimo</option><option value="agotado" <?=$f==='agotado'?'selected':''?>>Agotados</option></select></label><button>Aplicar filtros</button></form><div class="tabla"><table><thead><tr><th>Producto</th><th>Disponible</th><th>Mínimo de alerta</th><th>Estado</th><th>Próximo vencimiento</th><th></th></tr></thead><tbody><?php foreach($rs as $r):$bajo=$r['alerta_activa']&&(float)$r['utilizable']<=(float)$r['stock_minimo'];?><tr><td data-label="Producto"><strong><?=e($r['nombre'])?></strong><br><small><?=e($r['codigo'].' · '.$r['categoria'])?></small></td><td data-label="Disponible"><?=e(rtrim(rtrim(number_format((float)$r['utilizable'],4,',','.'),'0'),','))?> <?=e($r['unidad_base'])?></td><td data-label="Mínimo"><?=$r['alerta_activa']?e($r['stock_minimo'].' '.$r['unidad_base']):'Desactivada'?></td><td data-label="Estado"><span class="etiqueta <?=$bajo?'pendiente':''?>"><?=$bajo?((float)$r['utilizable']<=0?'Agotado':'Bajo mínimo'):'Disponible'?></span></td><td data-label="Vencimiento"><?=e($r['proximo_vencimiento']?:'No aplica')?></td><td><?php if(es_superadmin()):?><a href="index.php?r=producto.form&amp;id=<?=$r['id']?>">Configurar</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rs):?><div class="tarjeta estado-vacio">No hay productos para estos filtros.</div><?php endif;vista_fin();}
function form_producto_mejorado():void{$r=isset($_GET['id'])?fila('SELECT * FROM productos WHERE id=?',[id_get()]):[];vista_inicio($r?'Configurar producto':'Nuevo producto');?><div class="cabecera"><div><h1><?=$r?'Configurar producto':'Nuevo producto'?></h1><p>El mínimo se expresa en la unidad base de consumo.</p></div></div><form class="tarjeta form-grid" method="post" action="index.php?r=producto.guardar"><?=campo_csrf()?><input type="hidden" name="id" value="<?=e($r['id']??'')?>"><?php foreach(['codigo'=>'Código','nombre'=>'Nombre','categoria'=>'Categoría','unidad_base'=>'Unidad base','presentacion'=>'Presentación de compra'] as $k=>$n):?><label><?=$n?><input name="<?=$k?>" value="<?=e($r[$k]??'')?>" required></label><?php endforeach;?><label>Factor de conversión<input type="number" step="0.0001" min="0.0001" name="factor_conversion" value="<?=e($r['factor_conversion']??1)?>" required></label><label>Cantidad mínima para alertar<input type="number" step="0.0001" min="0" name="stock_minimo" value="<?=e($r['stock_minimo']??0)?>" required></label><label class="check"><input type="checkbox" name="alerta_activa" value="1" <?=($r['alerta_activa']??1)?'checked':''?>> Activar alerta en la campana</label><div class="acciones ancho"><button>Guardar configuración</button><a class="boton secundario" href="index.php?r=stock">Cancelar</a></div></form><?php vista_fin();}
function guardar_producto_mejorado():void{post();$id=(int)($_POST['id']??0);$p=[requerido('codigo',40),requerido('nombre',150),trim($_POST['categoria']??''),requerido('unidad_base',30),requerido('presentacion',80),(float)$_POST['factor_conversion'],(float)$_POST['stock_minimo'],isset($_POST['alerta_activa'])?1:0];if($id){$p[]=$id;ejecutar('UPDATE productos SET codigo=?,nombre=?,categoria=?,unidad_base=?,presentacion=?,factor_conversion=?,stock_minimo=?,alerta_activa=? WHERE id=?',$p);}else{ejecutar('INSERT INTO productos(codigo,nombre,categoria,unidad_base,presentacion,factor_conversion,stock_minimo,alerta_activa) VALUES (?,?,?,?,?,?,?,?)',$p);$id=(int)db()->lastInsertId();}auditar('configurar','productos',$id);flash('ok','Producto y alerta guardados.');redirigir('stock');}
function pagina_finanzas_mejorada():void{$desde=$_GET['desde']??date('Y-m-01');$hasta=$_GET['hasta']??date('Y-m-d');$medio=$_GET['medio']??'';$tipo=$_GET['tipo']??'todos';$ini=$desde.' 00:00:00';$fin=$hasta.' 23:59:59';$pagos=filas('SELECT p.fecha,"Cobro atención" concepto,p.medio,p.importe,"ingreso" tipo,pa.nombre paciente FROM pagos p JOIN cuentas c ON c.id=p.cuenta_id JOIN atenciones a ON a.id=c.atencion_id JOIN pacientes pa ON pa.id=a.paciente_id LEFT JOIN anulaciones_pago an ON an.pago_id=p.id WHERE an.id IS NULL AND p.fecha BETWEEN ? AND ?'.($medio?' AND p.medio=?':'').' ORDER BY p.fecha DESC',$medio?[$ini,$fin,$medio]:[$ini,$fin]);$otros=filas('SELECT fecha,descripcion concepto,medio,importe,tipo,NULL paciente FROM movimientos_financieros WHERE estado="vigente" AND fecha BETWEEN ? AND ?'.($medio?' AND medio=?':'').' ORDER BY fecha DESC',$medio?[$ini,$fin,$medio]:[$ini,$fin]);$mov=array_merge($pagos,$otros);if($tipo!=='todos')$mov=array_values(array_filter($mov,fn($m)=>$m['tipo']===$tipo));usort($mov,fn($a,$b)=>strcmp($b['fecha'],$a['fecha']));$ing=array_sum(array_map(fn($m)=>$m['tipo']==='ingreso'?(int)$m['importe']:0,$mov));$gas=array_sum(array_map(fn($m)=>$m['tipo']==='gasto'?(int)$m['importe']:0,$mov));vista_inicio('Finanzas');?><div class="cabecera"><div><span class="sobrelinea">CONTROL FINANCIERO</span><h1>Ingresos y gastos</h1><p>Detalle por fecha de pago; no confunde cargos emitidos con dinero recibido.</p></div></div><form class="tarjeta filtros-inline" method="get"><input type="hidden" name="r" value="finanzas"><label>Desde<input type="date" name="desde" value="<?=e($desde)?>"></label><label>Hasta<input type="date" name="hasta" value="<?=e($hasta)?>"></label><label>Tipo<select name="tipo"><option value="todos">Todos</option><option value="ingreso" <?=$tipo==='ingreso'?'selected':''?>>Ingresos</option><option value="gasto" <?=$tipo==='gasto'?'selected':''?>>Gastos</option></select></label><label>Medio<select name="medio"><option value="">Todos</option><?php foreach(['efectivo','transferencia','tarjeta'] as $m):?><option <?=$medio===$m?'selected':''?>><?=$m?></option><?php endforeach;?></select></label><button>Aplicar filtros</button></form><div class="rejilla"><article class="tarjeta metrica"><span>Ingresos recibidos</span><strong><?=clp($ing)?></strong></article><article class="tarjeta metrica"><span>Gastos pagados</span><strong><?=clp($gas)?></strong></article><article class="tarjeta metrica"><span>Flujo del período</span><strong><?=clp($ing-$gas)?></strong></article><article class="tarjeta metrica"><span>Movimientos</span><strong><?=count($mov)?></strong></article></div><h2>Detalle del período</h2><div class="tabla"><table><thead><tr><th>Fecha</th><th>Detalle</th><th>Tipo</th><th>Medio</th><th>Monto</th></tr></thead><tbody><?php foreach($mov as $m):?><tr><td data-label="Fecha"><?=e(utc_a_local($m['fecha']))?></td><td data-label="Detalle"><?=e($m['concepto'])?><?=$m['paciente']?' · '.e($m['paciente']):''?></td><td data-label="Tipo"><span class="etiqueta <?=$m['tipo']==='gasto'?'pendiente':''?>"><?=e($m['tipo'])?></span></td><td data-label="Medio"><?=e($m['medio'])?></td><td data-label="Monto" class="monto <?=$m['tipo']?>"><?=$m['tipo']==='gasto'?'−':'+'?><?=clp($m['importe'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$mov):?><div class="tarjeta estado-vacio">No hay movimientos para los filtros seleccionados.</div><?php endif;?><details class="tarjeta"><summary>Registrar otro ingreso o gasto</summary><form class="form-grid" action="index.php?r=finanza.guardar" method="post"><?=campo_csrf()?><label>Tipo<select name="tipo"><option value="gasto">Gasto</option><option value="ingreso">Otro ingreso</option></select></label><label>Categoría<input name="categoria" required></label><label>Descripción<input name="descripcion" required></label><label>Importe<input type="number" name="importe" min="1" required></label><label>Medio<select name="medio"><option>efectivo</option><option>transferencia</option><option>tarjeta</option></select></label><button>Registrar movimiento</button></form></details><?php vista_fin();}
function pagina_configuracion_marca():void{$nombre=configuracion_valor('clinica_nombre','ClinicVet');$logo=configuracion_valor('clinica_logo_archivo');$dias=configuracion_valor('alerta_vencimiento_dias','30');vista_inicio('Configuración');?><div class="cabecera"><div><span class="sobrelinea">PERSONALIZACIÓN</span><h1>Identidad de la clínica</h1><p>Este nombre y logo se mostrarán en la navegación del sistema.</p></div></div><form class="tarjeta form-grid" action="index.php?r=configuracion.guardar" method="post" enctype="multipart/form-data"><?=campo_csrf()?><section class="vista-marca ancho"><img src="<?=$logo?'index.php?r=configuracion.logo':'assets/logo.svg'?>" alt="Logo actual"><div><strong><?=e($nombre)?></strong><span>Vista actual</span></div></section><label class="ancho">Nombre de la clínica *<input name="clinica_nombre" value="<?=e($nombre)?>" required maxlength="100"><small>Aparece arriba del menú y en el título de las páginas.</small></label><label class="ancho campo-foto"><span>Logo de la clínica <small>(opcional)</small></span><input type="file" name="logo" accept="image/jpeg,image/png,image/webp"><small>JPEG, PNG o WebP, máximo 3 MB. Se recomienda formato cuadrado.</small></label><label>Días para alertar vencimientos<input type="number" min="1" max="365" name="alerta_vencimiento_dias" value="<?=e($dias)?>"></label><div class="acciones ancho"><button class="boton-grande">Guardar identidad</button></div></form><?php vista_fin();}
function guardar_configuracion_marca():void{post();$nombre=requerido('clinica_nombre',100);$dias=max(1,min(365,(int)($_POST['alerta_vencimiento_dias']??30)));ejecutar('INSERT INTO configuracion(clave,valor) VALUES ("clinica_nombre",?) ON DUPLICATE KEY UPDATE valor=VALUES(valor)',[$nombre]);ejecutar('INSERT INTO configuracion(clave,valor) VALUES ("alerta_vencimiento_dias",?) ON DUPLICATE KEY UPDATE valor=VALUES(valor)',[(string)$dias]);guardar_logo_clinica();auditar('actualizar','configuracion',null,null,['clinica_nombre'=>$nombre]);flash('ok','Nombre y logo de la clínica actualizados.');redirigir('configuracion');}
function resumen_atenciones_pacientes():never{$raw=(string)($_GET['ids']??'');$ids=array_values(array_unique(array_filter(array_map('intval',explode(',',$raw)),fn($id)=>$id>0)));if(!$ids||count($ids)>100)abortar(422,'Solicitud de pacientes inválida.');$marcas=implode(',',array_fill(0,count($ids),'?'));$rs=filas("SELECT p.id,COUNT(a.id) total,SUM(a.estado='finalizada') finalizadas,MAX(CASE WHEN a.estado!='anulada' THEN a.fecha_clinica END) ultima FROM pacientes p LEFT JOIN atenciones a ON a.paciente_id=p.id AND a.estado!='anulada' WHERE p.id IN ($marcas) GROUP BY p.id",$ids);$salida=[];foreach($rs as $r)$salida[(string)$r['id']]=['total'=>(int)$r['total'],'finalizadas'=>(int)$r['finalizadas'],'ultima'=>$r['ultima']?utc_a_local($r['ultima'],'d-m-Y'):null];header('Content-Type: application/json; charset=utf-8');header('Cache-Control: private, no-store');echo json_encode($salida,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);exit;}
function pagina_atenciones_filtrada():void{$q=trim((string)($_GET['q']??''));$estado=$_GET['estado']??'';$desde=$_GET['desde']??'';$hasta=$_GET['hasta']??'';$prof=(int)($_GET['profesional']??0);$sql='SELECT a.id,a.fecha_clinica,a.motivo,a.estado,p.nombre paciente,p.codigo,u.nombre profesional FROM atenciones a JOIN pacientes p ON p.id=a.paciente_id JOIN usuarios u ON u.id=a.responsable_id WHERE (p.nombre LIKE ? OR p.codigo LIKE ? OR a.motivo LIKE ?)';$like='%'.$q.'%';$params=[$like,$like,$like];if(in_array($estado,['borrador','finalizada','anulada'],true)){$sql.=' AND a.estado=?';$params[]=$estado;}if($desde){$sql.=' AND a.fecha_clinica>=?';$params[]=$desde.' 00:00:00';}if($hasta){$sql.=' AND a.fecha_clinica<=?';$params[]=$hasta.' 23:59:59';}if($prof){$sql.=' AND a.responsable_id=?';$params[]=$prof;}$sql.=' ORDER BY a.fecha_clinica DESC LIMIT 200';$rs=filas($sql,$params);$us=filas('SELECT id,nombre FROM usuarios WHERE activo=1 ORDER BY nombre');vista_inicio('Atenciones');?><div class="cabecera"><div><span class="sobrelinea">HISTORIAL CLÍNICO</span><h1>Atenciones</h1><p>Busca y filtra las consultas registradas.</p></div><a class="boton" href="index.php?r=recepcion">Nueva atención</a></div><form class="tarjeta filtros-atenciones" method="get"><input type="hidden" name="r" value="atenciones"><label class="filtro-busqueda">Paciente, código o motivo<input name="q" value="<?=e($q)?>" placeholder="Ej: Luna o control"></label><label>Desde<input type="date" name="desde" value="<?=e($desde)?>"></label><label>Hasta<input type="date" name="hasta" value="<?=e($hasta)?>"></label><label>Estado<select name="estado"><option value="">Todos</option><?php foreach(['borrador'=>'Borrador','finalizada'=>'Finalizada','anulada'=>'Anulada'] as $v=>$n):?><option value="<?=$v?>" <?=$estado===$v?'selected':''?>><?=$n?></option><?php endforeach;?></select></label><label>Profesional<select name="profesional"><option value="0">Todos</option><?php foreach($us as $u):?><option value="<?=$u['id']?>" <?=$prof===$u['id']?'selected':''?>><?=e($u['nombre'])?></option><?php endforeach;?></select></label><div class="acciones-filtro"><button>Filtrar</button><a class="boton secundario" href="index.php?r=atenciones">Limpiar</a></div></form><div class="resultado-cantidad"><?=count($rs)?> atención(es) encontrada(s)</div><div class="tabla"><table><thead><tr><th>Fecha</th><th>Paciente</th><th>Motivo</th><th>Profesional</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($rs as $r):?><tr><td data-label="Fecha"><?=e(utc_a_local($r['fecha_clinica']))?></td><td data-label="Paciente"><strong><?=e($r['paciente'])?></strong><br><small><?=e($r['codigo'])?></small></td><td data-label="Motivo"><?=e($r['motivo'])?></td><td data-label="Profesional"><?=e($r['profesional'])?></td><td data-label="Estado"><span class="etiqueta <?=$r['estado']==='borrador'?'pendiente':''?>"><?=e($r['estado'])?></span></td><td><a href="index.php?r=atencion.detalle&amp;id=<?=$r['id']?>">Ver atención</a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rs):?><div class="tarjeta estado-vacio"><h3>Sin resultados</h3><p>Prueba otro rango o limpia los filtros.</p></div><?php endif;vista_fin();}
function pagina_servicios_gestion():void{$editar=isset($_GET['id'])?fila('SELECT * FROM servicios WHERE id=?',[id_get()]):[];$estado=$_GET['estado']??'todos';$q=trim((string)($_GET['q']??''));$sql='SELECT s.*,(SELECT COUNT(*) FROM cargos c WHERE c.servicio_id=s.id) usos FROM servicios s WHERE (s.nombre LIKE ? OR s.categoria LIKE ?)';$params=['%'.$q.'%','%'.$q.'%'];if($estado==='activos'){$sql.=' AND s.activo=1';}elseif($estado==='inactivos'){$sql.=' AND s.activo=0';}$sql.=' ORDER BY s.activo DESC,s.nombre';$rs=filas($sql,$params);vista_inicio('Servicios');?><div class="cabecera"><div><span class="sobrelinea">CATÁLOGO</span><h1>Servicios</h1><p>Las tarifas nuevas no modifican los cargos históricos.</p></div></div><form class="tarjeta form-grid" action="index.php?r=servicio.guardar" method="post"><?=campo_csrf()?><input type="hidden" name="id" value="<?=e($editar['id']??'')?>"><label>Nombre<input name="nombre" value="<?=e($editar['nombre']??'')?>" required></label><label>Categoría<input name="categoria" value="<?=e($editar['categoria']??'')?>"></label><label>Tarifa CLP<input type="number" min="0" name="tarifa" value="<?=e($editar['tarifa']??'')?>" required></label><div class="acciones"><button><?=$editar?'Guardar cambios':'Crear servicio'?></button><?php if($editar):?><a class="boton secundario" href="index.php?r=servicios">Cancelar edición</a><?php endif;?></div></form><form class="tarjeta filtros-inline" method="get"><input type="hidden" name="r" value="servicios"><label>Buscar<input name="q" value="<?=e($q)?>"></label><label>Estado<select name="estado"><option value="todos">Todos</option><option value="activos" <?=$estado==='activos'?'selected':''?>>Activos</option><option value="inactivos" <?=$estado==='inactivos'?'selected':''?>>Inactivos</option></select></label><button>Filtrar</button></form><div class="tabla"><table><thead><tr><th>Servicio</th><th>Categoría</th><th>Tarifa</th><th>Estado</th><th>Uso</th><th>Acciones</th></tr></thead><tbody><?php foreach($rs as $r):?><tr><td data-label="Servicio"><strong><?=e($r['nombre'])?></strong></td><td data-label="Categoría"><?=e($r['categoria'])?></td><td data-label="Tarifa"><?=clp($r['tarifa'])?></td><td data-label="Estado"><span class="etiqueta <?=$r['activo']?'':'pendiente'?>"><?=$r['activo']?'Activo':'Inactivo'?></span></td><td data-label="Uso"><?=(int)$r['usos']?> cargo(s)</td><td data-label="Acciones"><div class="acciones-tabla"><a href="index.php?r=servicios&amp;id=<?=$r['id']?>">Editar</a><form method="post" action="index.php?r=servicio.estado&amp;id=<?=$r['id']?>"><?=campo_csrf()?><button class="enlace" type="submit"><?=$r['activo']?'Desactivar':'Activar'?></button></form><form method="post" action="index.php?r=servicio.eliminar&amp;id=<?=$r['id']?>"><?=campo_csrf()?><button class="enlace texto-peligro" type="submit" data-confirmar="¿Eliminar este servicio? Si tiene historial será desactivado.">Eliminar</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php vista_fin();}
function guardar_servicio_gestion():void{post();$id=(int)($_POST['id']??0);$p=[requerido('nombre',140),trim($_POST['categoria']??''),max(0,(int)($_POST['tarifa']??0))];if($id){$p[]=$id;ejecutar('UPDATE servicios SET nombre=?,categoria=NULLIF(?,""),tarifa=? WHERE id=?',$p);auditar('actualizar','servicios',$id);flash('ok','Servicio actualizado.');}else{ejecutar('INSERT INTO servicios(nombre,categoria,tarifa) VALUES (?,NULLIF(?,""),?)',$p);$id=(int)db()->lastInsertId();auditar('crear','servicios',$id);flash('ok','Servicio creado.');}redirigir('servicios');}
function cambiar_estado_servicio():void{post();$id=id_get();$s=fila('SELECT activo FROM servicios WHERE id=?',[$id]);if(!$s)abortar(404,'Servicio no encontrado.');ejecutar('UPDATE servicios SET activo=? WHERE id=?',[$s['activo']?0:1,$id]);auditar($s['activo']?'desactivar':'activar','servicios',$id);flash('ok',$s['activo']?'Servicio desactivado.':'Servicio activado.');redirigir('servicios');}
function eliminar_servicio():void{post();$id=id_get();$usos=(int)(fila('SELECT COUNT(*) n FROM cargos WHERE servicio_id=?',[$id])['n']??0);if($usos>0){ejecutar('UPDATE servicios SET activo=0 WHERE id=?',[$id]);auditar('desactivar_por_historial','servicios',$id);flash('aviso','El servicio tiene cargos históricos: fue desactivado, no eliminado.');}else{ejecutar('DELETE FROM servicios WHERE id=?',[$id]);auditar('eliminar','servicios',$id);flash('ok','Servicio eliminado.');}redirigir('servicios');}
function categorias_servicio_json():never{$rs=filas('SELECT id,codigo,etiqueta FROM catalogos WHERE tipo="categoria_servicio" AND activo=1 ORDER BY etiqueta');header('Content-Type: application/json; charset=utf-8');header('Cache-Control: private, no-store');echo json_encode($rs,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);exit;}
function pagina_categorias_servicio():void{$editar=isset($_GET['id'])?fila('SELECT * FROM catalogos WHERE id=? AND tipo="categoria_servicio"',[id_get()]):[];$rs=filas('SELECT c.*,(SELECT COUNT(*) FROM servicios s WHERE s.categoria=c.etiqueta) usos FROM catalogos c WHERE c.tipo="categoria_servicio" ORDER BY c.activo DESC,c.etiqueta');vista_inicio('Categorías de servicios');?><div class="cabecera"><div><span class="sobrelinea">MANTENEDOR</span><h1>Categorías de servicios</h1><p>Estas opciones aparecen en el formulario de servicios.</p></div><a class="boton secundario" href="index.php?r=servicios">Volver a servicios</a></div><form class="tarjeta form-grid" method="post" action="index.php?r=servicio.categoria.guardar"><?=campo_csrf()?><input type="hidden" name="id" value="<?=e($editar['id']??'')?>"><label>Nombre de la categoría *<input name="etiqueta" value="<?=e($editar['etiqueta']??'')?>" required maxlength="120" placeholder="Ej: Cirugía"></label><div class="acciones"><button><?=$editar?'Guardar cambios':'Crear categoría'?></button><?php if($editar):?><a class="boton secundario" href="index.php?r=servicio.categorias">Cancelar</a><?php endif;?></div></form><div class="tabla"><table><thead><tr><th>Categoría</th><th>Estado</th><th>Servicios</th><th>Acciones</th></tr></thead><tbody><?php foreach($rs as $r):?><tr><td><strong><?=e($r['etiqueta'])?></strong></td><td><span class="etiqueta <?=$r['activo']?'':'pendiente'?>"><?=$r['activo']?'Activa':'Inactiva'?></span></td><td><?=(int)$r['usos']?></td><td><div class="acciones-tabla"><a href="index.php?r=servicio.categorias&amp;id=<?=$r['id']?>">Editar</a><form method="post" action="index.php?r=servicio.categoria.estado&amp;id=<?=$r['id']?>"><?=campo_csrf()?><button class="enlace" type="submit"><?=$r['activo']?'Desactivar':'Activar'?></button></form><form method="post" action="index.php?r=servicio.categoria.eliminar&amp;id=<?=$r['id']?>"><?=campo_csrf()?><button class="enlace texto-peligro" type="submit" data-confirmar="¿Eliminar esta categoría?">Eliminar</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php vista_fin();}
function codigo_catalogo(string $texto):string{$texto=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$texto)?:$texto;$texto=mb_strtolower($texto);$texto=preg_replace('/[^a-z0-9]+/','_',$texto);return trim((string)$texto,'_').'_'.substr(bin2hex(random_bytes(3)),0,6);}
function guardar_categoria_servicio():void{post();$id=(int)($_POST['id']??0);$etiqueta=requerido('etiqueta',120);if($id){$anterior=fila('SELECT etiqueta FROM catalogos WHERE id=? AND tipo="categoria_servicio"',[$id]);if(!$anterior)abortar(404,'Categoría no encontrada.');$pdo=db();try{$pdo->beginTransaction();ejecutar('UPDATE catalogos SET etiqueta=? WHERE id=?',[$etiqueta,$id]);ejecutar('UPDATE servicios SET categoria=? WHERE categoria=?',[$etiqueta,$anterior['etiqueta']]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();abortar(422,'La categoría ya existe o no pudo actualizarse.');}auditar('actualizar','categoria_servicio',$id);}else{try{ejecutar('INSERT INTO catalogos(tipo,codigo,etiqueta) VALUES ("categoria_servicio",?,?)',[codigo_catalogo($etiqueta),$etiqueta]);$id=(int)db()->lastInsertId();}catch(PDOException){abortar(422,'La categoría ya existe.');}auditar('crear','categoria_servicio',$id);}flash('ok','Categoría guardada.');redirigir('servicio.categorias');}
function cambiar_estado_categoria_servicio():void{post();$id=id_get();$c=fila('SELECT activo FROM catalogos WHERE id=? AND tipo="categoria_servicio"',[$id]);if(!$c)abortar(404,'Categoría no encontrada.');ejecutar('UPDATE catalogos SET activo=? WHERE id=?',[$c['activo']?0:1,$id]);auditar($c['activo']?'desactivar':'activar','categoria_servicio',$id);flash('ok',$c['activo']?'Categoría desactivada.':'Categoría activada.');redirigir('servicio.categorias');}
function eliminar_categoria_servicio():void{post();$id=id_get();$c=fila('SELECT etiqueta FROM catalogos WHERE id=? AND tipo="categoria_servicio"',[$id]);if(!$c)abortar(404,'Categoría no encontrada.');$usos=(int)(fila('SELECT COUNT(*) n FROM servicios WHERE categoria=?',[$c['etiqueta']])['n']??0);if($usos){ejecutar('UPDATE catalogos SET activo=0 WHERE id=?',[$id]);flash('aviso','La categoría está en uso: fue desactivada, no eliminada.');auditar('desactivar_por_uso','categoria_servicio',$id);}else{ejecutar('DELETE FROM catalogos WHERE id=?',[$id]);flash('ok','Categoría eliminada.');auditar('eliminar','categoria_servicio',$id);}redirigir('servicio.categorias');}
function tipos_seguimiento():array{return ['vacuna'=>'Vacuna','desparasitacion'=>'Desparasitación','control'=>'Control clínico','examen'=>'Examen','medicamento'=>'Medicamento','procedimiento'=>'Procedimiento','otro'=>'Otro'];}
function contador_seguimientos_json():never{$r=fila('SELECT COUNT(*) total,SUM(fecha_programada<CURRENT_DATE) vencidos,SUM(fecha_programada BETWEEN CURRENT_DATE AND DATE_ADD(CURRENT_DATE,INTERVAL 7 DAY)) proximos FROM seguimientos WHERE estado="pendiente"');header('Content-Type: application/json; charset=utf-8');echo json_encode(['total'=>(int)$r['total'],'vencidos'=>(int)$r['vencidos'],'proximos'=>(int)$r['proximos']]);exit;}
function pagina_seguimientos():void{$estado=$_GET['estado']??'pendientes';$tipo=$_GET['tipo']??'';$q=trim((string)($_GET['q']??''));$desde=$_GET['desde']??'';$hasta=$_GET['hasta']??'';$sql='SELECT s.*,p.nombre paciente,p.codigo,t.nombre tutor,t.telefono FROM seguimientos s JOIN pacientes p ON p.id=s.paciente_id JOIN tutores t ON t.id=p.tutor_id WHERE (p.nombre LIKE ? OR p.codigo LIKE ? OR t.nombre LIKE ? OR s.titulo LIKE ?)';$l='%'.$q.'%';$params=[$l,$l,$l,$l];if($estado==='pendientes')$sql.=' AND s.estado="pendiente"';elseif(in_array($estado,['completado','cancelado'],true)){$sql.=' AND s.estado=?';$params[]=$estado;}elseif($estado==='vencidos')$sql.=' AND s.estado="pendiente" AND s.fecha_programada<CURRENT_DATE';elseif($estado==='proximos')$sql.=' AND s.estado="pendiente" AND s.fecha_programada BETWEEN CURRENT_DATE AND DATE_ADD(CURRENT_DATE,INTERVAL 30 DAY)';if(isset(tipos_seguimiento()[$tipo])){$sql.=' AND s.tipo=?';$params[]=$tipo;}if($desde){$sql.=' AND s.fecha_programada>=?';$params[]=$desde;}if($hasta){$sql.=' AND s.fecha_programada<=?';$params[]=$hasta;}$sql.=' ORDER BY (s.estado="pendiente") DESC,s.fecha_programada ASC LIMIT 250';$rs=filas($sql,$params);$tot=fila('SELECT SUM(estado="pendiente") pendientes,SUM(estado="pendiente" AND fecha_programada<CURRENT_DATE) vencidos,SUM(estado="pendiente" AND fecha_programada BETWEEN CURRENT_DATE AND DATE_ADD(CURRENT_DATE,INTERVAL 7 DAY)) semana FROM seguimientos');vista_inicio('Seguimientos');?><div class="cabecera"><div><span class="sobrelinea">RECORDATORIOS INTERNOS</span><h1>Seguimientos</h1><p>Vacunas, controles y tareas futuras confirmadas por el equipo clínico.</p></div><a class="boton" href="index.php?r=seguimiento.form">Nuevo seguimiento</a></div><div class="rejilla"><a class="tarjeta metrica" href="index.php?r=seguimientos&amp;estado=pendientes"><span>Pendientes</span><strong><?=(int)$tot['pendientes']?></strong></a><a class="tarjeta metrica alerta-stock" href="index.php?r=seguimientos&amp;estado=vencidos"><span>Vencidos</span><strong><?=(int)$tot['vencidos']?></strong></a><a class="tarjeta metrica" href="index.php?r=seguimientos&amp;estado=proximos"><span>Próximos 7 días</span><strong><?=(int)$tot['semana']?></strong></a></div><form class="tarjeta filtros-atenciones" method="get"><input type="hidden" name="r" value="seguimientos"><label class="filtro-busqueda">Paciente, tutor o recordatorio<input name="q" value="<?=e($q)?>"></label><label>Desde<input type="date" name="desde" value="<?=e($desde)?>"></label><label>Hasta<input type="date" name="hasta" value="<?=e($hasta)?>"></label><label>Estado<select name="estado"><?php foreach(['pendientes'=>'Pendientes','proximos'=>'Próximos 30 días','vencidos'=>'Vencidos','completado'=>'Completados','cancelado'=>'Cancelados','todos'=>'Todos'] as $v=>$n):?><option value="<?=$v?>" <?=$estado===$v?'selected':''?>><?=$n?></option><?php endforeach;?></select></label><label>Tipo<select name="tipo"><option value="">Todos</option><?php foreach(tipos_seguimiento() as $v=>$n):?><option value="<?=$v?>" <?=$tipo===$v?'selected':''?>><?=$n?></option><?php endforeach;?></select></label><div class="acciones-filtro"><button>Filtrar</button><a class="boton secundario" href="index.php?r=seguimientos">Limpiar</a></div></form><div class="tabla"><table><thead><tr><th>Fecha</th><th>Paciente y tutor</th><th>Seguimiento</th><th>Contacto</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($rs as $r):$vencido=$r['estado']==='pendiente'&&$r['fecha_programada']<date('Y-m-d');?><tr><td data-label="Fecha"><strong><?=e(date('d-m-Y',strtotime($r['fecha_programada'])))?></strong><?php if($vencido):?><br><span class="etiqueta pendiente">Vencido</span><?php endif;?></td><td data-label="Paciente"><a href="index.php?r=paciente.ficha&amp;id=<?=$r['paciente_id']?>"><strong><?=e($r['paciente'])?></strong></a><br><small><?=e($r['tutor'].' · '.($r['telefono']?:'sin teléfono'))?></small></td><td data-label="Seguimiento"><strong><?=e(tipos_seguimiento()[$r['tipo']])?></strong> · <?=e($r['titulo'])?><?php if($r['observaciones']):?><br><small><?=e($r['observaciones'])?></small><?php endif;?></td><td data-label="Contacto"><?=e($r['contacto_resultado']?:'No registrado')?></td><td data-label="Estado"><span class="etiqueta <?=$r['estado']==='pendiente'?'pendiente':''?>"><?=e($r['estado'])?></span></td><td data-label="Acciones"><div class="acciones-tabla"><a href="index.php?r=seguimiento.form&amp;id=<?=$r['id']?>">Editar</a><?php if($r['estado']==='pendiente'):?><form method="post" action="index.php?r=seguimiento.estado&amp;id=<?=$r['id']?>"><?=campo_csrf()?><input type="hidden" name="estado" value="completado"><button class="enlace">Completar</button></form><form method="post" action="index.php?r=seguimiento.estado&amp;id=<?=$r['id']?>"><?=campo_csrf()?><input type="hidden" name="estado" value="cancelado"><button class="enlace texto-peligro" data-confirmar="¿Cancelar este seguimiento?">Cancelar</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rs):?><div class="tarjeta estado-vacio"><h3>Sin seguimientos</h3><p>No hay registros para los filtros seleccionados.</p></div><?php endif;vista_fin();}
function form_seguimiento():void{$id=(int)($_GET['id']??0);$r=$id?fila('SELECT * FROM seguimientos WHERE id=?',[$id]):[];if($id&&!$r)abortar(404,'Seguimiento no encontrado.');$pid=(int)($_GET['paciente_id']??($r['paciente_id']??0));$ps=filas('SELECT p.id,p.nombre,p.codigo,t.nombre tutor FROM pacientes p JOIN tutores t ON t.id=p.tutor_id WHERE p.estado="activo" ORDER BY p.nombre');vista_inicio($r?'Editar seguimiento':'Nuevo seguimiento');?><div class="cabecera"><div><span class="sobrelinea">RECORDATORIO INTERNO</span><h1><?=$r?'Editar seguimiento':'Nuevo seguimiento'?></h1><p>La fecha debe ser indicada o confirmada por el profesional.</p></div></div><form class="tarjeta form-grid" action="index.php?r=seguimiento.guardar" method="post"><?=campo_csrf()?><input type="hidden" name="id" value="<?=$id?>"><label class="ancho">Paciente *<select name="paciente_id" required><option value="">Seleccionar</option><?php foreach($ps as $p):?><option value="<?=$p['id']?>" <?=$pid===$p['id']?'selected':''?>><?=e($p['nombre'].' · '.$p['codigo'].' · '.$p['tutor'])?></option><?php endforeach;?></select></label><label>Tipo *<select name="tipo" required><?php foreach(tipos_seguimiento() as $v=>$n):?><option value="<?=$v?>" <?=($r['tipo']??'control')===$v?'selected':''?>><?=$n?></option><?php endforeach;?></select></label><label>Fecha programada *<input type="date" name="fecha_programada" value="<?=e($r['fecha_programada']??'')?>" required></label><label class="ancho">Qué se debe recordar *<input name="titulo" value="<?=e($r['titulo']??'')?>" required maxlength="160" placeholder="Ej: Segunda dosis vacuna séxtuple"></label><label>Prioridad<select name="prioridad"><option value="normal">Normal</option><option value="alta" <?=($r['prioridad']??'')==='alta'?'selected':''?>>Alta</option></select></label><label class="ancho">Observaciones<textarea name="observaciones" maxlength="1000"><?=e($r['observaciones']??'')?></textarea></label><label class="ancho">Resultado del contacto <small>(opcional)</small><input name="contacto_resultado" value="<?=e($r['contacto_resultado']??'')?>" maxlength="255" placeholder="Ej: Tutor confirmó que llamará para reservar"></label><div class="acciones ancho"><button>Guardar seguimiento</button><a class="boton secundario" href="index.php?r=seguimientos">Cancelar</a></div></form><?php vista_fin();}
function guardar_seguimiento():void{post();$id=(int)($_POST['id']??0);$tipo=$_POST['tipo']??'';if(!isset(tipos_seguimiento()[$tipo]))abortar(422,'Tipo de seguimiento inválido.');$fecha=$_POST['fecha_programada']??'';if(!DateTimeImmutable::createFromFormat('Y-m-d',$fecha))abortar(422,'Fecha inválida.');$contacto=trim($_POST['contacto_resultado']??'');$p=[(int)$_POST['paciente_id'],$tipo,requerido('titulo',160),$fecha,$_POST['prioridad']==='alta'?'alta':'normal',trim($_POST['observaciones']??''),$contacto,$contacto?gmdate('Y-m-d H:i:s'):null];if(!fila('SELECT id FROM pacientes WHERE id=?',[$p[0]]))abortar(422,'Paciente inválido.');if($id){$p[]=$id;ejecutar('UPDATE seguimientos SET paciente_id=?,tipo=?,titulo=?,fecha_programada=?,prioridad=?,observaciones=NULLIF(?,""),contacto_resultado=NULLIF(?,""),contactado_en=? WHERE id=? AND estado="pendiente"',$p);auditar('actualizar','seguimientos',$id);}else{$p[]=usuario()['id'];ejecutar('INSERT INTO seguimientos(paciente_id,tipo,titulo,fecha_programada,prioridad,observaciones,contacto_resultado,contactado_en,creado_por) VALUES (?,?,?,?,?,NULLIF(?,""),NULLIF(?,""),?,?)',$p);$id=(int)db()->lastInsertId();auditar('crear','seguimientos',$id);}flash('ok','Seguimiento guardado.');redirigir('seguimientos');}
function cambiar_estado_seguimiento():void{post();$id=id_get();$estado=$_POST['estado']??'';if(!in_array($estado,['completado','cancelado'],true))abortar(422,'Estado inválido.');ejecutar('UPDATE seguimientos SET estado=?,completado_por=?,completado_en=UTC_TIMESTAMP() WHERE id=? AND estado="pendiente"',[$estado,usuario()['id'],$id]);auditar($estado,'seguimientos',$id);flash('ok',$estado==='completado'?'Seguimiento completado.':'Seguimiento cancelado.');redirigir('seguimientos');}
function registrar_contacto_seguimiento():void{post();$id=id_get();ejecutar('UPDATE seguimientos SET contacto_resultado=?,contactado_en=UTC_TIMESTAMP() WHERE id=? AND estado="pendiente"',[requerido('resultado',255),$id]);auditar('contactar','seguimientos',$id);redirigir('seguimientos');}
function form_producto_operativo():void{$id=(int)($_GET['id']??0);$r=$id?fila('SELECT * FROM productos WHERE id=?',[$id]):[];if($id&&!$r)abortar(404,'Producto no encontrado.');$lotes=$id?filas('SELECT * FROM lotes WHERE producto_id=? ORDER BY (saldo_base>0) DESC,vencimiento IS NULL,vencimiento,codigo_lote',[$id]):[];$atenciones=$id?filas('SELECT a.id,a.fecha_clinica,p.nombre paciente FROM atenciones a JOIN pacientes p ON p.id=a.paciente_id WHERE a.estado!="anulada" ORDER BY a.fecha_clinica DESC LIMIT 100'):[];vista_inicio($r?'Producto y existencias':'Nuevo producto');?><div class="cabecera"><div><span class="sobrelinea">INVENTARIO</span><h1><?=$r?'Producto y existencias':'Nuevo producto'?></h1><p>Configura la alerta y administra entradas o consumos por lote.</p></div><a class="boton secundario" href="index.php?r=stock">Volver al stock</a></div><form class="tarjeta form-grid" method="post" action="index.php?r=producto.guardar"><?=campo_csrf()?><input type="hidden" name="id" value="<?=e($r['id']??'')?>"><?php foreach(['codigo'=>'Código','nombre'=>'Nombre','categoria'=>'Categoría','unidad_base'=>'Unidad base','presentacion'=>'Presentación de compra'] as $k=>$n):?><label><?=$n?><input name="<?=$k?>" value="<?=e($r[$k]??'')?>" required></label><?php endforeach;?><label>Factor de conversión<input type="number" step="0.0001" min="0.0001" name="factor_conversion" value="<?=e($r['factor_conversion']??1)?>" required></label><label>Cantidad mínima para alertar<input type="number" step="0.0001" min="0" name="stock_minimo" value="<?=e($r['stock_minimo']??0)?>" required></label><label class="check"><input type="checkbox" name="alerta_activa" value="1" <?=($r['alerta_activa']??1)?'checked':''?>> Activar alerta en la campana</label><div class="acciones ancho"><button>Guardar configuración</button></div></form><?php if($id):?><div class="rejilla"><section class="tarjeta"><h2>Registrar entrada</h2><form class="form-grid" method="post" action="index.php?r=stock.entrada"><?=campo_csrf()?><input type="hidden" name="producto_id" value="<?=$id?>"><input type="hidden" name="operacion_id" value="<?=operacion_id()?>"><label>Cantidad en <?=e($r['unidad_base'])?><input type="number" step="0.0001" min="0.0001" name="cantidad" required></label><label>Código de lote<input name="codigo_lote" maxlength="80"></label><label>Vencimiento<input type="date" name="vencimiento"></label><label>Costo por <?=e($r['unidad_base'])?><input type="number" step="0.0001" min="0" name="costo_unitario_base" value="0" required></label><label class="ancho">Motivo<input name="motivo" value="Compra / reposición" maxlength="500"></label><button>Registrar entrada</button></form></section><section class="tarjeta"><h2>Registrar consumo</h2><?php $disponibles=array_filter($lotes,fn($l)=>(float)$l['saldo_base']>0&&(!$l['vencimiento']||$l['vencimiento']>=date('Y-m-d')));if($disponibles):?><form class="form-grid" method="post" action="index.php?r=stock.consumo"><?=campo_csrf()?><input type="hidden" name="operacion_id" value="<?=operacion_id()?>"><label class="ancho">Lote<select name="lote_id" required><?php foreach($disponibles as $l):?><option value="<?=$l['id']?>"><?=e(($l['codigo_lote']?:'Sin código').' · '.$l['saldo_base'].' '.$r['unidad_base'].($l['vencimiento']?' · vence '.$l['vencimiento']:''))?></option><?php endforeach;?></select></label><label>Cantidad<input type="number" step="0.0001" min="0.0001" name="cantidad" required></label><label>Atención (opcional)<select name="atencion_id"><option value="0">Sin asociar</option><?php foreach($atenciones as $a):?><option value="<?=$a['id']?>"><?=e($a['paciente'].' · '.utc_a_local($a['fecha_clinica'],'d-m-Y'))?></option><?php endforeach;?></select></label><label class="ancho">Motivo<input name="motivo" value="Consumo clínico" maxlength="500"></label><button>Registrar consumo</button></form><?php else:?><p>No hay lotes vigentes con saldo disponible.</p><?php endif;?></section></div><h2>Lotes</h2><div class="tabla"><table><thead><tr><th>Lote</th><th>Vencimiento</th><th>Saldo</th><th>Costo unitario</th><th>Estado</th></tr></thead><tbody><?php foreach($lotes as $l):$vencido=$l['vencimiento']&&$l['vencimiento']<date('Y-m-d');?><tr><td><?=e($l['codigo_lote']?:'Sin código')?></td><td><?=e($l['vencimiento']?:'No aplica')?></td><td><?=e($l['saldo_base'].' '.$r['unidad_base'])?></td><td><?=clp($l['costo_unitario_base']??0)?></td><td><span class="etiqueta <?=$vencido||(float)$l['saldo_base']<=0?'pendiente':''?>"><?=$vencido?'Vencido':((float)$l['saldo_base']<=0?'Agotado':'Disponible')?></span></td></tr><?php endforeach;?></tbody></table></div><?php if(!$lotes):?><div class="tarjeta estado-vacio">Aún no hay entradas para este producto.</div><?php endif;endif;vista_fin();}
